window.INGREDIENTS = (window.INGREDIENTS || []).concat([
{id:"aceto-balsamico-tradizionale",cat:"condiments",name:{en:"Aceto Balsamico Tradizionale DOP",fr:"Vinaigre balsamique traditionnel de Modène DOP"},latin:"Vitis vinifera",
origin:{en:"Modena and Reggio Emilia, Italy",fr:"Modène et Reggio d’Émilie, Italie"},season:[],
flavor:["sweet","sour","woody","rich"],
story:{en:"Cooked grape must works its way down a battery of casks — oak, cherry, chestnut, mulberry, juniper — each year giving a little to the barrel below and taking a little from the one above, for twelve years at the very least. Every bottle the tasting panel passes is sold in the same 100 ml bulb, a shape drawn by the car designer Giorgetto Giugiaro.",
fr:"Le moût de raisin cuit descend une batterie de fûts — chêne, cerisier, châtaignier, mûrier, genévrier — chaque année en cédant un peu au tonneau du dessous et en prenant un peu à celui du dessus, douze ans au minimum. Toute bouteille agréée par le jury de dégustation est vendue dans le même flacon de 100 ml, dessiné par le styliste automobile Giorgetto Giugiaro."},
tip:{en:"It is already cooked, so it goes on at the table and never in the pan: a scant teaspoon over parmesan, strawberries or a rib of beef once it is off the fire. Anything you would pour is not this product.",
fr:"Il est déjà cuit : il se met à table et jamais dans la casserole, une petite cuillère à peine sur du parmesan, des fraises ou une côte de bœuf hors du feu. Ce que l’on peut verser n’est pas ce produit-là."},
pairs:["parmesan","strawberry","prosciutto","cote-de-boeuf","fig","pear"],
svg:'<path class="f2 sf" d="M44 22h8v14q10 6 10 18v14q0 8-8 8H42q-8 0-8-8V54q0-12 10-18z"/><path class="s" d="M42 22h12v-4H42z"/><path class="f3" d="M36 58h24v10q0 6-6 6H42q-6 0-6-6z"/><circle class="dot" cx="48" cy="84" r="2.5"/>'},

{id:"aka-miso",cat:"condiments",name:{en:"Aka miso",fr:"Miso rouge (aka)"},latin:"Long-aged rice and soybean paste",
origin:{en:"Tohoku & northern Japan",fr:"Tohoku & nord du Japon"},season:[],
flavor:["salty","umami","rich","earthy"],
story:{en:"When Date Masamune founded Sendai around 1600 he built a miso works inside the castle town to keep his troops in rations — commonly counted as Japan's first miso factory — and his red paste was the one that held on campaign when other domains' spoiled. The colour is the record of that keeping: one to three years of Maillard browning, with nothing added to darken it.",
fr:"Quand Date Masamune fonda Sendai vers 1600, il installa dans la ville close une fabrique de miso pour ravitailler ses troupes — tenue pour la première du Japon — et son miso rouge fut celui qui tenait en campagne quand celui des autres fiefs tournait. La couleur est la trace de cette garde : un à trois ans de réaction de Maillard, sans rien qui la fonce."},
tip:{en:"It carries roughly twice the salt of a white miso, so swap it in at half the weight and taste before going further. Where saikyo caramelises sweetly under a grill, aka simply goes acrid — keep it for soups, braises and long simmers, not glazes.",
fr:"Il porte environ deux fois plus de sel qu’un miso blanc : substituez-le à moitié poids et goûtez avant d’en remettre. Là où le saikyo caramélise sous le gril, l’aka devient âcre — gardez-le pour les soupes, les braisés et les mijotés longs, pas pour les glaçages."},
pairs:["pork","leek","ginger","garlic","butter","potato","carrot","black-radish"],
svg:'<path class="f2 sf" d="M28 34h40l-4 38H32z"/><path class="s" d="M28 44h40M30 60h36M40 34v38M56 34v38"/><ellipse class="f1 sf" cx="48" cy="32" rx="18" ry="5"/><ellipse class="f3 sf" cx="48" cy="25" rx="8" ry="4"/>'},

{id:"alaea-salt",cat:"condiments",name:{en:"Alaea red Hawaiian salt",fr:"Sel rouge d’Hawaï (alaea)"},latin:"Halite (NaCl)",
origin:{en:"Kauai, Hawaii",fr:"Kauai, Hawaï"},season:[],
flavor:["salty","earthy","mild"],
story:{en:"The colour is alaea, an iron-rich volcanic clay stirred into sea salt, added as much to hold the salt through the wet months and to bless canoes and houses as to season food. The ponds at Hanapepe on Kauai are still worked by hand by a few families, and by custom that salt is never sold, only given.",
fr:"La couleur vient de l’alaea, une argile volcanique riche en oxyde de fer que l’on mêle au sel marin : elle servait autant à tenir le sel pendant la saison humide qu’à bénir les pirogues et les maisons. Les bassins de Hanapepe, à Kauai, sont encore travaillés à la main par quelques familles, et l’usage veut que ce sel-là ne se vende pas : il se donne."},
tip:{en:"The clay dulls under heat, so keep it for the finish — a pinch on kalua pork, on poke or on raw fish as it goes out. It takes up water faster than white salt: store it dry and away from the stove or it sets into a brick.",
fr:"L’argile s’éteint à la cuisson : gardez-le pour la finition, une pincée sur un porc kalua, un poke ou du poisson cru au moment d’envoyer. Il prend l’humidité plus vite qu’un sel blanc, conservez-le au sec et loin du piano sinon il prend en bloc."},
pairs:["pork","tuna","avocado","sweet-potato","lime","coconut"],
svg:'<path class="f2 sf" d="M22 64q10-22 26-22t26 22z"/><path class="s" d="M32 58q8-8 16-8t16 8"/><path class="f3 sf" d="M20 64h56v6H20z"/><circle class="dot" cx="26" cy="52" r="2"/><circle class="dot" cx="70" cy="54" r="2"/>'},

{id:"amazake",cat:"condiments",name:{en:"Amazake",fr:"Amazaké"},latin:"Saccharified rice koji (Aspergillus oryzae)",
origin:{en:"Japan",fr:"Japon"},season:[],
flavor:["sweet","milky","mild"],
story:{en:"Its sweetness is glucose, cut out of the rice starch by koji enzymes; the process is simply stopped before any yeast is involved, which is why there is no alcohol in it. In Edo it was a summer drink, sold cold in the street against heat exhaustion, and it remains a summer season-word in haiku — a surprise to anyone who has only met it hot at a New Year shrine.",
fr:"Sa douceur est du glucose, découpé dans l’amidon du riz par les enzymes du koji ; le procédé s’arrête simplement avant toute levure, d’où l’absence d’alcool. À Edo, c’était une boisson d’été, vendue froide dans la rue contre les coups de chaleur, et il reste un mot de saison estival en haïku — ce qui surprend qui ne l’a bu que chaud, au sanctuaire du Nouvel An."},
tip:{en:"Hold it at 55-60°C for eight hours: below that it sours, and much above 65°C the enzymes die and it never sweetens. Blended smooth it replaces sugar in a dressing or a batter at roughly twice the weight, and it will restart a sluggish sourdough.",
fr:"Maintenez-le entre 55 et 60 °C pendant huit heures : en dessous il tourne, et bien au-delà de 65 °C les enzymes meurent et il ne sucrera jamais. Mixé lisse, il remplace le sucre d’une vinaigrette ou d’une pâte à raison du double du poids, et relance un levain paresseux."},
pairs:["ginger","strawberry","yuzu","sesame","cream","lemon"],
svg:'<path class="f1 sf" d="M32 38h32l-4 30q-1 6-12 6t-12-6z"/><path class="s" d="M32 46q16 6 32 0"/><ellipse class="dot" cx="44" cy="56" rx="3" ry="2"/><ellipse class="dot" cx="54" cy="62" rx="3" ry="2"/><ellipse class="dot" cx="48" cy="50" rx="3" ry="2"/>'},

{id:"anchovy-paste",cat:"condiments",name:{en:"Anchovy paste",fr:"Pâte d’anchois"},latin:"Engraulis encrasicolus",
origin:{en:"Mediterranean",fr:"Méditerranée"},season:[],
flavor:["salty","umami","briny","marine"],
story:{en:"The direct descendant of garum, the fermented fish sauce Rome put on everything and shipped in amphorae across the empire. Its glutamates dissolve completely into a sauce, which is why it deepens a dish without ever tasting of fish.",
fr:"La descendante directe du garum, la sauce de poisson fermentée que Rome mettait partout et expédiait en amphores dans tout l’empire. Ses glutamates se dissolvent entièrement dans une sauce, d’où son pouvoir d’approfondir un plat sans jamais avoir goût de poisson."},
tip:{en:"Melt it in warm oil before anything else joins the pan. It disappears, and nobody will identify it.",
fr:"Faites-la fondre dans l’huile tiède avant tout le reste. Elle disparaît, et personne ne l’identifiera."},
pairs:["garlic","olive-oil","lemon","parsley","butter","chili","tomato","capers"],
svg:'<path class="f1 sf" d="M38 74V42h20v32z"/><path class="s" d="M38 50h20"/><path class="s" d="M42 60q6 4 12 0M42 66q6 4 12 0"/>'},

{id:"balsamic",cat:"condiments",name:{en:"Balsamic vinegar",fr:"Vinaigre balsamique"},latin:"Aceto balsamico",
origin:{en:"Modena, Italy",fr:"Modène, Italie"},season:[],
flavor:["sweet","sour","woody","rich"],
story:{en:"In Modena’s attics, cooked grape must sleeps through decades in a diminishing row of barrels — oak, chestnut, cherry — each lending its wood to the dream. Families started a battery of barrels at a daughter’s birth: her dowry, aged twenty-five years.",
fr:"Dans les greniers de Modène, le moût de raisin cuit dort des décennies dans une rangée décroissante de fûts — chêne, châtaignier, cerisier — chacun prêtant son bois au songe. Les familles lançaient une batterie de fûts à la naissance d’une fille : sa dot, vieillie vingt-cinq ans."},
tip:{en:"The real thing is syrup-thick and needs no reduction; supermarket balsamic improves simmered down by half. A few drops on strawberries or parmesan — never a flood.",
fr:"Le vrai est épais comme un sirop et n’a nul besoin de réduction ; celui de supermarché s’améliore réduit de moitié. Quelques gouttes sur des fraises ou du parmesan — jamais un déluge."},
pairs:["strawberry","tomato","parmesan","fig","onion","beetroot"],
svg:'<path class="f3 sf" d="M45 24h6v10q8 4 8 14v22q0 8-11 8t-11-8V48q0-10 8-14z"/><path class="f1" d="M40 58h16v8q0 4-8 4t-8-4z"/>'},

{id:"banyuls-vinegar",cat:"condiments",name:{en:"Banyuls vinegar",fr:"Vinaigre de Banyuls"},latin:"Vinaigre de Banyuls",
origin:{en:"Roussillon, France",fr:"Roussillon, France"},season:[],
flavor:["sour","sweet","nutty","rich"],
story:{en:"Made from Banyuls, a fortified sweet wine from the terraced vineyards above the Mediterranean, and aged in oak barrels left outdoors through the seasons. The result is closer to sherry vinegar than to any French one.",
fr:"Fait à partir du banyuls, vin doux naturel des terrasses surplombant la Méditerranée, et vieilli en fûts de chêne laissés dehors au fil des saisons. Le résultat est plus proche du vinaigre de Xérès que d’aucun français."},
tip:{en:"Its sweetness lets it stand alone — a spoonful on a warm salad of duck or foie gras needs no oil at all.",
fr:"Sa douceur lui permet de se suffire — une cuillerée sur une salade tiède de canard ou de foie gras n’appelle aucune huile."},
pairs:["foie-gras","duck","walnut","olive-oil","fig","shallot","blue-cheese","hazelnut"],
svg:'<path class="f1 sf" d="M40 76V40h16v36z"/><path class="s" d="M40 48h16M44 62h8"/><path class="f1 sf" d="M44 36V25h8v11z"/>'},

{id:"black-garlic",cat:"condiments",rare:true,name:{en:"Black garlic",fr:"Ail noir"},latin:"Allium sativum (aged)",
origin:{en:"Korea & Japan",fr:"Corée & Japon"},season:[],
flavor:["sweet","umami","rich","tangy"],
story:{en:"Whole heads of garlic held warm and humid for weeks until the Maillard reaction — the chemistry of bread crusts and seared steaks — turns each clove black, soft and sweet as a balsamic date. An ancient Asian preparation that modern chefs adopted almost overnight in the 2000s.",
fr:"Des têtes d’ail entières tenues au chaud et à l’humide pendant des semaines, jusqu’à ce que la réaction de Maillard — la chimie des croûtes de pain et des viandes saisies — rende chaque gousse noire, fondante et douce comme une datte balsamique. Une préparation asiatique ancienne que les chefs ont adoptée presque du jour au lendemain dans les années 2000."},
tip:{en:"No bite remains — use it as a condiment, not a garlic. Crush a clove into butter for a steak, or into mayonnaise for anything fried.",
fr:"Il ne reste aucun mordant — utilisez-le comme condiment, pas comme ail. Écrasez une gousse dans un beurre pour une viande, ou dans une mayonnaise pour toute friture."},
pairs:["beef","miso","mushroom","butter","balsamic","dark-chocolate"],
svg:'<path class="f3 sf" d="M48 28q3 10 12 16 8 6 8 14a20 16 0 01-40 0q0-8 8-14 9-6 12-16z"/><path class="f1" d="M40 46q-3 12-2 26M56 46q3 12 2 26M48 34v40" fill="none"/><path class="s" d="M40 46q-3 12-2 26M56 46q3 12 2 26M48 34v40" stroke-width="1.6"/>'},

{id:"caper-berries",cat:"condiments",name:{en:"Caper berries",fr:"Câprons (câpres à queue)"},latin:"Capparis spinosa",
origin:{en:"Mediterranean scrub and old walls",fr:"Garrigues et vieux murs méditerranéens"},season:[7,8,9],
flavor:["briny","tangy","mild"],
story:{en:"The caper bush flowers for a single day — open at dawn, spent by dusk — and the berry is what follows if the bud was left on the plant. A grower has to choose: pick the buds for capers, or let them go and take the fruit, since one bush will not give a full crop of both.",
fr:"Le câprier ne fleurit qu’un seul jour — la fleur s’ouvre à l’aube et est fanée au soir — et le câpron est ce qui suit si l’on a laissé le bouton sur le pied. Le producteur doit choisir : cueillir les boutons pour les câpres ou laisser venir le fruit, car un pied ne donne pas les deux récoltes en entier."},
tip:{en:"Serve them whole with the stalk on, at room temperature, and do not chop them: the seeds are the texture you are buying. Rinse briefly only — a long soak leaves them limp and hollow-tasting.",
fr:"Servez-les entiers avec la queue, à température ambiante, et ne les hachez pas : les pépins sont la texture que vous achetez. Rincez-les brièvement, un long dessalage les laisse mous et creux."},
pairs:["anchovy","olive-oil","manzanilla-sherry","jamon-serrano","tomato","sea-bass"],
svg:'<path class="f2 sf" d="M48 40q12 6 12 20t-12 16q-12-2-12-16t12-20z"/><path class="s" d="M48 40V20"/><path class="f1 sf" d="M48 28q10-8 18-4-6 10-18 4z"/><path class="s" d="M48 46q6 12 2 28"/><circle class="dot" cx="43" cy="58" r="1.8"/><circle class="dot" cx="54" cy="64" r="1.8"/>'},

{id:"capers",cat:"condiments",name:{en:"Capers",fr:"Câpres"},latin:"Capparis spinosa",
origin:{en:"Mediterranean basin",fr:"Bassin méditerranéen"},season:[],
flavor:["briny","tangy","floral","pungent"],
story:{en:"A caper is a flower that never got to bloom: the buds are picked at dawn, one by one, from bushes that grow out of stone walls, then cured in salt or brine. On the island of Pantelleria, the harvest is a UNESCO-listed art. Smallest ones — nonpareilles — are the most prized.",
fr:"La câpre est une fleur qui n’a jamais pu éclore : les boutons se cueillent à l’aube, un à un, sur des buissons qui poussent dans les murs de pierre, puis se confisent au sel ou en saumure. Sur l’île de Pantelleria, la récolte est un art classé à l’UNESCO. Les plus petites — les nonpareilles — sont les plus prisées."},
tip:{en:"Salt-packed capers taste finer than brined — rinse them well. Fried crisp in olive oil, they become little savoury fireworks for fish.",
fr:"Les câpres au sel sont plus fines que celles en saumure — rincez-les bien. Frites croustillantes à l’huile d’olive, elles deviennent de petits feux d’artifice salés pour le poisson."},
pairs:["lemon","tomato","anchovy","cod","olive","parsley"],
svg:'<path class="s" d="M40 68q-2-10 4-16M52 66q0-8 4-12M46 70q-1-6 2-10"/><path class="f2" d="M41 48a4.5 4.5 0 109 0 4.5 4.5 0 10-9 0M53 50a4 4 0 108 0 4 4 0 10-8 0M44 58a3.5 3.5 0 107 0 3.5 3.5 0 10-7 0" transform="translate(0 -6)"/>'},

{id:"chili-crisp",cat:"condiments",name:{en:"Chilli crisp",fr:"Huile pimentée croustillante (chili crisp)"},latin:"Capsicum annuum",
origin:{en:"Guiyang, Guizhou, China",fr:"Guiyang, Guizhou, Chine"},season:[],
flavor:["hot","umami","toasty","pungent"],
story:{en:"Tao Huabi sold noodles in Guiyang and gave away the chilli oil she made to go with them; when customers began coming only for the oil, she started bottling it in the mid-1990s. She could not read or write, and had her own face printed on the label so buyers would know the jar was hers.",
fr:"Tao Huabi vendait des nouilles à Guiyang et offrait l’huile pimentée qui les accompagnait ; quand les clients ne sont plus venus que pour l’huile, elle s’est mise à la mettre en pots, au milieu des années 1990. Ne sachant ni lire ni écrire, elle a fait imprimer son propre visage sur l’étiquette pour qu’on reconnaisse le pot."},
tip:{en:"The crunch is the product and it does not survive the pan, so spoon it over food that is already plated. Keep the solids submerged in the oil and the jar lasts months; a spoon that has touched a hot dish goes back wet and softens it within a week.",
fr:"Le croquant est le produit et il ne survit pas à la poêle : servez-la à la cuillère sur une assiette déjà dressée. Gardez les morceaux immergés dans l’huile et le pot tient des mois ; une cuillère qui a touché un plat chaud le ramollit en une semaine."},
pairs:["egg","rice","silken-tofu","cucumber","pak-choi","avocado"],
svg:'<path class="f2 sf" d="M34 36h28v28q0 6-6 6H40q-6 0-6-6z"/><path class="s" d="M32 30h32v6H32z"/><path class="f3" d="M36 52h24v12q0 4-4 4H40q-4 0-4-4z"/><path class="f1 sf" d="M70 52q7 0 7 7t-7 7q-7 0-7-7t7-7z"/><path class="s" d="M72 52l4-24"/><circle class="dot" cx="44" cy="60" r="2"/>'},

{id:"chinese-sesame-paste",cat:"condiments",name:{en:"Chinese sesame paste",fr:"Pâte de sésame grillé chinoise"},latin:"Sesamum indicum",
origin:{en:"Northern China",fr:"Nord de la Chine"},season:[],
flavor:["nutty","toasty","bitter","rich"],
story:{en:"Zhima jiang is ground from seed roasted almost to the point of burning, which is why it is brown where tahini is pale, and why it tastes of the roast rather than of the seed. In Beijing it is the whole of the dipping sauce for lamb hotpot, loosened with fermented bean curd and chive flower and nothing else.",
fr:"Le zhima jiang est broyé à partir de graines torréfiées presque jusqu’au brûlé : c’est pourquoi il est brun là où le tahini est pâle, et pourquoi il a le goût de la torréfaction plutôt que de la graine. À Pékin, il constitue à lui seul la sauce de la fondue de mouton, détendu de fromage de soja fermenté et de fleurs de ciboule, rien d’autre."},
tip:{en:"It sets like cement at the bottom of the jar: loosen it a spoon of liquid at a time, cold and slowly, or it seizes and splits. For a noodle sauce, one part paste to one part water first, then the soy and the vinegar.",
fr:"Il prend comme du ciment au fond du pot : détendez-le une cuillerée de liquide à la fois, à froid et lentement, sinon il tranche. Pour une sauce à nouilles, une part de pâte pour une part d’eau d’abord, la sauce soja et le vinaigre ensuite."},
pairs:["soba-noodles","cucumber","chinkiang-vinegar","furu","lamb","sichuan-pepper"],
svg:'<path class="f2 sf" d="M22 48h52q-2 22-26 22T22 48z"/><path class="f3 sf" d="M28 48q6-6 20-6t20 6z"/><path class="s" d="M62 44l12-18"/><circle class="dot" cx="34" cy="38" r="1.8"/><circle class="dot" cx="43" cy="31" r="1.8"/><circle class="dot" cx="55" cy="34" r="1.8"/>'},

{id:"chinkiang-vinegar",cat:"condiments",name:{en:"Chinkiang vinegar",fr:"Vinaigre noir de Chinkiang"},latin:"Oryza sativa var. glutinosa",
origin:{en:"Zhenjiang, Jiangsu",fr:"Zhenjiang, Jiangsu"},season:[],
flavor:["sour","smoky","toasty"],
story:{en:"It is fermented solid rather than liquid: glutinous rice is mixed with wheat bran into a damp mash turned by hand in open vats, and that bran is where the smoke and the toast come from. Zhenjiang holds a protected origin designation, and the serious jars are labelled by the number of years they stood outside.",
fr:"La fermentation se fait en milieu solide et non liquide : le riz gluant est mêlé au son de blé en une masse humide retournée à la main dans des cuves ouvertes, et c'est ce son qui apporte le fumé et le grillé. Zhenjiang bénéficie d'une appellation d'origine protégée, et les bons flacons portent le nombre d'années passées dehors."},
tip:{en:"Add it off the heat — the aromatics are volatile and a long simmer leaves nothing but the acid. For a dumpling dip work to roughly two parts vinegar to one of ginger julienne with a pinch of sugar; the sugar is what makes it read as balsamic rather than merely sour.",
fr:"Ajoutez-le hors du feu : les arômes sont volatils et une longue cuisson ne laisse que l'acidité. Pour une sauce à raviolis, comptez environ deux parts de vinaigre pour une de gingembre en julienne avec une pincée de sucre ; c'est le sucre qui le fait basculer du côté du balsamique plutôt que de l'aigre."},
pairs:["ginger","garlic","soy-sauce","sesame-oil","pork","chili-crisp","sugar","crab"],
svg:'<path class="f2 sf" d="M41 18h14v7H41z"/><path class="f3 sf" d="M42 25h12v9l8 12v30q0 4-4 4H38q-4 0-4-4V46l8-12z"/><path class="f1 sf" d="M38 54h20v14H38z"/><path class="s" d="M42 60h12M42 64h8"/>'},

{id:"cider-vinegar",cat:"condiments",name:{en:"Cider vinegar",fr:"Vinaigre de cidre"},latin:"Acetum pomorum",
origin:{en:"Normandy & Brittany",fr:"Normandie & Bretagne"},season:[],
flavor:["sour","fruity","tangy","sweet"],
story:{en:"The cloudy strand that forms in an unfiltered bottle is the mother — a living mat of bacteria and cellulose that turns alcohol into acid. It is not spoilage, and it can be lifted out and used to start the next batch.",
fr:"Le voile trouble qui se forme dans une bouteille non filtrée est la mère — un tapis vivant de bactéries et de cellulose qui change l’alcool en acide. Ce n’est pas une altération, et on peut la prélever pour lancer la fournée suivante."},
tip:{en:"It is gentler than wine vinegar, so use a little more. It suits pork, cabbage and anything with apple in it.",
fr:"Il est plus doux que le vinaigre de vin : forcez un peu la dose. Il va au porc, au chou et à tout ce qui contient de la pomme."},
pairs:["apple","pork","red-cabbage","mustard","honey","onion","thyme","black-pepper"],
svg:'<path class="f2 sf" d="M40 76V40h16v36z"/><path class="s" d="M40 48h16"/><circle class="f2 sf" cx="48" cy="30" r="6"/>'},

{id:"coconut-milk",cat:"condiments",name:{en:"Coconut milk",fr:"Lait de coco"},latin:"Cocos nucifera",
origin:{en:"Indo-Pacific coasts",fr:"Côtes indo-pacifiques"},season:[],
flavor:["creamy","sweet","rich","milky"],
story:{en:"Not the water that sloshes inside the nut, but the cream pressed from its grated flesh — the invention of every coconut coast at once. In Thai and Indian kitchens it plays the role butter and cream play in France: the velvet that carries the spices.",
fr:"Non pas l’eau qui clapote dans la noix, mais la crème pressée de sa chair râpée — l’invention simultanée de toutes les côtes à cocotiers. Dans les cuisines thaïes et indiennes, il joue le rôle du beurre et de la crème en France : le velours qui porte les épices."},
tip:{en:"Don’t shake the tin: the thick cream on top is for frying your curry paste, the thin milk below for simmering.",
fr:"Ne secouez pas la boîte : la crème épaisse du dessus sert à frire la pâte de curry, le lait clair du dessous à mijoter."},
pairs:["chili","cilantro","ginger","rice","mango","shrimp","turmeric"],
svg:'<circle class="f3 sf" cx="48" cy="54" r="19"/><path class="f1 sf" d="M48 54a19 19 0 010-38v19z" transform="rotate(30 48 45)"/><path class="f1 sf" d="M34 46a19 14 0 0128 0 22 22 0 01-28 0z"/><path class="s" d="M42 30l2 4M52 30l-2 4"/>'},

{id:"coconut-vinegar",cat:"condiments",name:{en:"Coconut vinegar",fr:"Vinaigre de coco"},latin:"Cocos nucifera",
origin:{en:"The Philippines",fr:"Philippines"},season:[],
flavor:["sour","tangy","mild","fruity"],
story:{en:"Sukang tuba begins as tuba, the sap a climber cuts from the coconut flower spike twice a day, which ferments into palm wine and then, left alone, into vinegar. The mother keeps working in the bottle, so it stays cloudy and its acidity is still moving when you buy it.",
fr:"Le sukang tuba commence en tuba, la sève que le grimpeur entaille deux fois par jour sur la hampe florale du cocotier, qui fermente en vin de palme puis, laissée seule, en vinaigre. La mère continue de travailler dans la bouteille : il reste trouble et son acidité bouge encore quand vous l’achetez."},
tip:{en:"It is softer than cider or rice vinegar, around 4%, so a kinilaw or an adobo takes more of it than a recipe written for wine vinegar suggests — start at half again as much. Shake before pouring: the sediment carries most of the flavour.",
fr:"Il est plus doux qu’un vinaigre de cidre ou de riz, autour de 4 % : un kinilaw ou un adobo en demande plus qu’une recette écrite pour du vinaigre de vin, comptez une fois et demie. Secouez avant de verser, le dépôt porte l’essentiel du goût."},
pairs:["pork","garlic","black-pepper","ginger","bay-leaf","soy-sauce"],
svg:'<path class="f3 sf" d="M22 46a26 26 0 0 0 52 0z"/><path class="f1" d="M27 48h42a21 21 0 0 1-42 0z"/><path class="s" d="M22 46h52"/><path class="s" d="M34 58q6 6 14 4t12-8"/><path class="f1 sf" d="M48 22q5 8 5 11t-5 3-5-3 5-11z"/>'},

{id:"colatura-d-anchois",cat:"condiments",name:{en:"Colatura di alici",fr:"Colatura d'anchois"},latin:"Engraulis encrasicolus (anchovy liquid)",
origin:{en:"Cetara, Amalfi coast",fr:"Cetara, côte amalfitaine"},season:[],
flavor:["umami","salty","briny","marine"],
story:{en:"Cetara packs its anchovies in salt inside small chestnut barrels called terzigni, then pierces the base after two or three years and lets the amber liquid fall drop by drop. Legend has it that medieval monks found the method by accident, when brine seeped through the worn staves of old wine casks; the sauce only received its protected designation in 2020.",
fr:"À Cetara, les anchois sont tassés au sel dans de petits fûts de châtaignier, les terzigni, dont on perce le fond au bout de deux ou trois ans pour recueillir goutte à goutte un liquide ambré. La légende veut que des moines médiévaux l'aient découvert par accident, la saumure suintant entre les douves usées de vieux fûts à vin ; l'appellation protégée, elle, ne date que de 2020."},
tip:{en:"Cook the pasta in unsalted water and stir the colatura in off the heat, about a tablespoon for 100 g, with raw garlic and oil. Boiled, it loses its sweetness and turns flatly fishy.",
fr:"Cuisez les pâtes à l'eau non salée et incorporez la colatura hors du feu, environ une cuillère à soupe pour 100 g, avec ail cru et huile. Bouillie, elle perd sa douceur et ne laisse qu'un goût de poisson plat."},
pairs:["garlic","olive-oil","parsley","lemon","chili","tomato"],
svg:'<path class="f1 sf" d="M42 22h12v12l8 12v28q0 5-5 5H39q-5 0-5-5V46l8-12z"/><path class="f3" d="M34 56h28v18q0 5-5 5H39q-5 0-5-5z"/><path class="f2 sf" d="M36 58h24v12H36z"/><path class="s" d="M40 20h16"/>'},

{id:"cornichon",cat:"condiments",name:{en:"Cornichon",fr:"Cornichon"},latin:"Cucumis sativus",
origin:{en:"France",fr:"France"},season:[],
flavor:["sour","salty","fresh","tangy"],
story:{en:"The French kind is picked at three or four centimetres and pickled in vinegar with tarragon and pearl onions, which makes it sharp — as opposed to the American dill pickle, brined and sour rather than vinegared. They are not interchangeable.",
fr:"Le français se cueille à trois ou quatre centimètres et se confit au vinaigre avec estragon et petits oignons, ce qui le rend mordant — à l’inverse du pickle américain, saumuré et acide plutôt que vinaigré. Ils ne sont pas interchangeables."},
tip:{en:"Chop them into a sauce gribiche or a rémoulade at the last moment. Left to sit, they leach vinegar and thin the whole thing.",
fr:"Hachez-les dans une gribiche ou une rémoulade au dernier moment. Laissés à attendre, ils rendent du vinaigre et délayent l’ensemble."},
pairs:["mustard","capers","egg","tarragon","shallot","parsley","beef","butter"],
svg:'<path class="f2 sf" d="M38 30q8 0 10 10t2 30q-2 8-8 6t-6-16 0-26 2-4z"/><circle class="dot" cx="40" cy="46" r="1.4"/><circle class="dot" cx="45" cy="58" r="1.4"/>'},

{id:"curing-salt",cat:"condiments",name:{en:"Curing salt (nitrited salt)",fr:"Sel nitrité"},latin:"NaCl + NaNO2",
origin:{en:"The charcuterie workshop",fr:"Le laboratoire de charcuterie"},season:[],
flavor:["salty","mild"],
story:{en:"For centuries charcutiers used saltpetre without knowing why it worked; in the 1890s German food chemists showed that it was the nitrite bacteria made from it, not the nitrate itself, that fixed the colour and held botulism off. Nitrite was then blended straight into the salt, and the mixture dyed pink so nobody could take it for table salt.",
fr:"Pendant des siècles, les charcutiers ont employé le salpêtre sans savoir pourquoi il agissait ; dans les années 1890, des chimistes allemands ont montré que c’était le nitrite formé par les bactéries, et non le nitrate lui-même, qui fixait la couleur et tenait le botulisme à distance. On a dès lors mélangé le nitrite directement au sel, et coloré le mélange en rose pour que nul ne le prenne pour du sel de table."},
tip:{en:"Dose it by the weight of the meat, never by taste: 20 g of 0.6% nitrited salt per kilo is the standard rate, and that is the total salt, not an addition to it. It turns toxic well before it would taste wrong, so weigh it on a scale that reads to a tenth of a gram and never scale a recipe by eye.",
fr:"Dosez au poids de la viande, jamais au goût : 20 g de sel nitrité à 0,6 % par kilo est le taux courant, et c’est le sel total, pas un supplément. Il devient toxique bien avant de sembler trop salé : pesez-le sur une balance au dixième de gramme et ne multipliez jamais une recette à l’œil."},
pairs:["pork","poitrine-de-porc","beef","black-pepper","juniper","garlic"],
svg:'<path class="f2 sf" d="M28 46q0 14 14 14t14-14z"/><path class="s" d="M26 46h32"/><path class="s" d="M56 46l18-12"/><path class="f1 sf" d="M74 30q6-2 6 3t-6 3z"/><circle class="dot" cx="36" cy="52" r="1.8"/><circle class="dot" cx="45" cy="54" r="1.8"/>'},

{id:"dark-soy-sauce",cat:"condiments",name:{en:"Dark soy sauce",fr:"Sauce soja noire (lao chou)"},latin:"Glycine max",
origin:{en:"Southern China",fr:"Chine du Sud"},season:[],
flavor:["umami","sweet","rich"],
story:{en:"The name lao chou, old draw, records the order of the vat: sheng chou, the fresh draw, is taken first, and this darker liquid comes off later after further ageing and a dose of molasses. It is the colour ingredient of red-braising, and it is measurably less salty than the light soy it keeps getting confused with.",
fr:"Le nom lao chou, « vieux tirage », dit l'ordre de la cuve : le sheng chou, le tirage frais, se prélève en premier, et ce liquide plus sombre ne vient qu'ensuite, après vieillissement et ajout de mélasse. C'est l'ingrédient de couleur du braisage rouge, et il est mesurablement moins salé que la sauce claire à laquelle on le confond sans cesse."},
tip:{en:"Dose it by the teaspoon and put it in early, into the hot oil or the braising liquid, so the sugars caramelise instead of tasting raw. Swapping it one-for-one for light soy is the standard failure: the dish comes out black and underseasoned.",
fr:"Dosez-la à la cuillère à café et mettez-la tôt, dans l'huile chaude ou le liquide de braisage, pour que les sucres caramélisent au lieu de rester crus. L'erreur classique est de la substituer volume pour volume à la sauce claire : le plat ressort noir et sous-assaisonné."},
pairs:["sheng-chou","star-anise","ginger","pork-belly","sugar","shaoxing-wine","spring-onion","garlic"],
svg:'<path class="f3 sf" d="M44 26h8v8q10 6 10 20v18q0 6-6 6H40q-6 0-6-6V54q0-14 10-20z"/><path class="s" d="M44 26q-7-2-9-7"/><circle class="dot" cx="32" cy="15" r="2.5"/><path class="f1 sf" d="M40 58h16v12H40z"/>'},

{id:"doenjang",cat:"condiments",name:{en:"Doenjang",fr:"Doenjang (pâte de soja coréenne)"},latin:"Glycine max",
origin:{en:"Korea",fr:"Corée"},season:[],
flavor:["umami","earthy","pungent"],
story:{en:"It begins as meju: boiled soybeans pounded into bricks and hung in straw rope through the winter so that airborne bacilli and moulds settle on them, with no cultivated koji anywhere in the process. The bricks then go into brine in an onggi jar, and what is poured off becomes soy sauce while what stays behind is doenjang — one ferment, two products.",
fr:"Tout commence par le meju : des fèves de soja cuites, pilées en briques, suspendues à des cordes de paille tout l'hiver pour que bacilles et moisissures de l'air s'y installent — sans aucun koji cultivé dans le procédé. Les briques passent ensuite en saumure dans une jarre onggi, et ce que l'on soutire devient la sauce soja tandis que ce qui reste au fond est le doenjang : une seule fermentation, deux produits."},
tip:{en:"Slake it in a ladleful of hot broth before it goes into the pot or it will sit there in lumps. It runs roughly twice as salty as white miso, so season the dish with it first and only reach for salt at the very end.",
fr:"Délayez-le dans une louche de bouillon chaud avant de l'ajouter, sinon il reste en grumeaux. Il est environ deux fois plus salé que le miso blanc : assaisonnez d'abord avec lui et ne rectifiez au sel qu'à la toute fin."},
pairs:["garlic","silken-tofu","gochujang","sesame-oil","spring-onion","zucchini","anchovy","pork"],
svg:'<path class="f2 sf" d="M30 46q0-12 18-12t18 12v14q0 16-18 16t-18-16z"/><path class="f3 sf" d="M34 34h28v5H34z"/><circle class="dot" cx="48" cy="29" r="3"/><path class="s" d="M38 50q10 4 20 0"/>'},

{id:"doubanjiang",cat:"condiments",name:{en:"Doubanjiang",fr:"Doubanjiang"},latin:"豆瓣醬",
origin:{en:"Pixian, Sichuan",fr:"Pixian, Sichuan"},season:[],
flavor:["salty","umami","hot","earthy"],
story:{en:"Sichuan calls it the soul of its cooking. The best comes from Pixian and is fermented in open jars for three years or more, stirred by hand and covered against rain — the paste darkens from red to near black as it ages.",
fr:"Le Sichuan l’appelle l’âme de sa cuisine. Le meilleur vient de Pixian et fermente en jarres ouvertes trois ans ou davantage, remué à la main et couvert contre la pluie — la pâte fonce du rouge au presque noir en vieillissant."},
tip:{en:"Fry it in oil until the fat turns red before anything else goes in. That step is not optional — it is where the flavour is released.",
fr:"Faites-le frire dans l’huile jusqu’à ce que le gras rougisse avant d’ajouter quoi que ce soit. Cette étape n’est pas facultative — c’est là que le goût se libère."},
pairs:["sichuan-pepper","garlic","ginger","spring-onion","soy-sauce","chili","pork","rice"],
svg:'<path class="f1 sf" d="M34 72V44h28v28z"/><path class="s" d="M34 52h28"/><circle class="dot" cx="42" cy="62" r="2"/><circle class="dot" cx="54" cy="64" r="2"/>'},

{id:"dry-vermouth",cat:"condiments",name:{en:"Dry vermouth",fr:"Vermouth sec"},latin:"Artemisia absinthium",
origin:{en:"Marseillan, Languedoc",fr:"Marseillan, Languedoc"},season:[],
flavor:["bitter","herbal","warm"],
story:{en:"The name is German — Wermut, wormwood — and the wormwood is not decoration: it is the bitterness that survives a reduction, at the point where white wine has gone flat and sour. At Marseillan the base wines spend a year outdoors in oak, through sun, lagoon mist and frost, before a single botanical is infused into them.",
fr:"Le nom vient de l’allemand Wermut, l’absinthe, et cette amertume n’est pas un ornement : c’est elle qui tient à la réduction, là où un vin blanc tourne plat et acide. À Marseillan, les vins de base passent une année dehors, en fûts de chêne, soleil, brumes de l’étang et gelées, avant qu’on y infuse la moindre plante."},
tip:{en:"Swap it for white wine in a fish sauce volume for volume, but stop the reduction earlier — the bitterness concentrates faster than the acidity does. An open bottle is a wine, not a spirit: refrigerate it and finish it inside a month.",
fr:"Remplacez le vin blanc volume pour volume dans une sauce de poisson, mais arrêtez la réduction plus tôt : l’amertume se concentre plus vite que l’acidité. Une bouteille ouverte est un vin, pas un alcool — au réfrigérateur, et finie dans le mois."},
pairs:["dover-sole","shallot","cream","butter","mussel","fennel"],
svg:'<path class="f2 sf" d="M44 14h8v18c0 5 6 6 6 12v34a4 4 0 0 1-4 4H42a4 4 0 0 1-4-4V44c0-6 6-7 6-12z"/><path class="f1 sf" d="M38 54h20v14H38z"/><path class="s" d="M42 61h12"/><path class="f3 sf" d="M43 10h10v5H43z"/>'},

{id:"english-mustard",cat:"condiments",name:{en:"English mustard powder",fr:"Moutarde anglaise (en poudre)"},latin:"Brassica juncea / Sinapis alba",
origin:{en:"Norwich, England",fr:"Norwich, Angleterre"},season:[],
flavor:["pungent","hot","bitter"],
story:{en:"Jeremiah Colman began milling at Norwich in 1814 and sold flour rather than paste: husk sifted out, brown seed for heat and yellow for body, the mixing left to the cook. The heat does not exist in the tin — it is made in the bowl, when water lets an enzyme in the seed reach the compound it cuts.",
fr:"Jeremiah Colman a commencé à moudre à Norwich en 1814 et vendait de la farine plutôt qu’une pâte : son de graine tamisé, graine brune pour la force et jaune pour le corps, le mélange laissé au cuisinier. Le feu n’existe pas dans la boîte, il se fabrique dans le bol quand l’eau permet à une enzyme de la graine de rencontrer le composé qu’elle coupe."},
tip:{en:"Mix with cold water only — hot water or vinegar kills the enzyme and leaves bitterness without heat — and let it stand ten minutes. It peaks around half an hour and is flat within two, so mix it for the service you are sending, not for the morning before.",
fr:"Délayez à l’eau froide seulement — l’eau chaude ou le vinaigre tuent l’enzyme et vous laissent l’amertume sans le feu — et laissez reposer dix minutes. La force culmine vers une demi-heure et a disparu en deux : préparez-la pour le service que vous envoyez, pas pour la veille."},
pairs:["beef","cheddar","jambon-de-paris","leek","honey","cream"],
svg:'<path class="f2 sf" d="M38 48h30v22H38z"/><path class="f1 sf" d="M38 48l6-6h30l-6 6z"/><path class="s" d="M68 48l6-6v22l-6 6"/><path class="f3 sf" d="M20 70q6-14 12-14t12 14z"/><path class="s" d="M18 70h56"/>'},

{id:"shrimp-paste",cat:"condiments",name:{en:"Fermented shrimp paste (belacan)",fr:"Pâte de crevette fermentée (belacan)"},latin:"Acetes spp.",
origin:{en:"Coastal Southeast Asia",fr:"Côtes d’Asie du Sud-Est"},season:[],
flavor:["umami","salty","pungent","briny"],
story:{en:"Belacan is made from Acetes, a shrimp barely a centimetre long, salted, left to break down in the sun and pressed into blocks that ferment for weeks — the smell is proteins being taken apart. A good block cuts like a firm cheese; one that crumbles was dried too fast and will give only salt.",
fr:"Le belacan se fait avec l’Acetes, une crevette d’à peine un centimètre, salée, laissée se défaire au soleil puis pressée en blocs qui fermentent des semaines : l’odeur, ce sont des protéines que l’on démonte. Un bon bloc se coupe comme un fromage ferme ; celui qui s’effrite a séché trop vite et ne donnera que du sel."},
tip:{en:"Toast it before it goes anywhere near a dish: a thin slice, two minutes a side in a dry pan, until the kitchen is unbearable and it snaps rather than bends. A pea-sized piece seasons a curry paste for four; untoasted and undosed it flattens everything else.",
fr:"Torréfiez-le avant tout emploi : une tranche fine, deux minutes de chaque côté à la poêle sèche, jusqu’à ce que la cuisine devienne irrespirable et qu’il casse net. Un morceau gros comme un pois assaisonne une pâte de curry pour quatre ; cru et non dosé, il écrase tout le reste."},
pairs:["chili","garlic","shallot","lime","lemongrass","tamarind-paste"],
svg:'<path class="f3 sf" d="M30 46q18-8 36 0 4 14-4 22-14 6-28 0-4-8-4-22z"/><path class="f1 sf" d="M24 46q10-8 24-8t24 8q-12 4-24 4t-24-4z"/><path class="s" d="M40 58q8 4 16 0"/><path class="s" d="M44 24q10-3 15 5-6 7-15 3-4-4 0-8z"/><circle class="dot" cx="57" cy="26" r="1.6"/>'},

{id:"fish-sauce",cat:"condiments",rare:true,name:{en:"Fish sauce",fr:"Nuoc-mâm"},latin:"Engraulidae (fermented)",
origin:{en:"Vietnam & Thailand",fr:"Vietnam & Thaïlande"},season:[],
flavor:["salty","umami","pungent","rich"],
story:{en:"Anchovies and salt, stacked in wooden barrels under the tropical sun for a year — the direct heir of Rome’s garum, still pressed the old way in Cetara, Italy, as colatura. The first amber run of the barrel, nhĩ, is graded and prized like an extra-virgin oil.",
fr:"Des anchois et du sel, empilés en fûts de bois sous le soleil tropical pendant un an — l’héritier direct du garum romain, encore pressé à l’ancienne à Cetara, en Italie, sous le nom de colatura. La première coulée ambrée du fût, le nhĩ, se classe et se dispute comme une huile extra-vierge."},
tip:{en:"Smell the bottle, then trust the pot: cooked, it sheds its roar and leaves pure depth. A teaspoon secretly improves a bolognese or a vinaigrette.",
fr:"Sentez la bouteille, puis faites confiance à la marmite : cuite, elle perd son rugissement et ne laisse que la profondeur. Une cuillerée améliore en secret une bolognaise ou une vinaigrette."},
pairs:["chili","garlic","ginger","peanut","beef","coconut-milk"],
svg:'<path class="f1 sf" d="M43 26h10v8l5 8v28q0 8-10 8t-10-8V42l5-8z"/><path class="f2" d="M38 52h20v14q0 6-10 6t-10-6z"/><path class="s" d="M43 26h10" stroke-width="1.6"/>'},

{id:"maldon-flake-salt",cat:"condiments",name:{en:"Flake sea salt (Maldon)",fr:"Sel en flocons de Maldon"},latin:"Halite (NaCl)",
origin:{en:"Blackwater estuary, Essex, England",fr:"Estuaire de la Blackwater, Essex, Angleterre"},season:[],
flavor:["salty","briny","mild"],
story:{en:"Salt has been made on the Blackwater since before the Domesday survey recorded pans there; the present works has boiled estuary water in open pans since 1882. The hollow pyramids form only at the surface of a slow, shallow boil — the shape is a consequence of the pan, not an additive.",
fr:"On fait du sel sur la Blackwater depuis avant que le Domesday Book n’y recense des salines ; la maison actuelle fait bouillir l’eau de l’estuaire en bassins ouverts depuis 1882. Les pyramides creuses ne se forment qu’à la surface d’une ébullition lente et peu profonde : la forme vient du bassin, pas d’un additif."},
tip:{en:"Crush it between thumb and finger over the plate — it is built to shatter, and dissolving it in a liquid wastes the texture and the money together. It weighs about half what fine salt does by volume, so a recipe's teaspoon of table salt is not a teaspoon of this.",
fr:"Écrasez-le entre le pouce et l’index au-dessus de l’assiette : il est fait pour éclater, et le fondre dans un liquide gâche la texture comme l’argent. Il pèse à peu près la moitié d’un sel fin à volume égal : la cuillère de sel fin d’une recette n’est pas une cuillère de celui-ci."},
pairs:["cote-de-boeuf","dark-chocolate","tomato","butter","potato","oyster"],
svg:'<path class="f1 sf" d="M48 30L66 62H30z"/><path class="s" d="M48 30v32M48 62l-13-7M48 62l13-7"/><path class="f2 sf" d="M28 56L36 70H20z"/><path class="f2 sf" d="M68 58L76 72H60z"/>'},

{id:"fleur-de-sel-guerande",cat:"condiments",name:{en:"Fleur de sel de Guérande",fr:"Fleur de sel de Guérande"},latin:"Halite (NaCl)",
origin:{en:"Guérande marshes, Brittany",fr:"Marais salants de Guérande, Bretagne"},season:[6,7,8,9],
flavor:["salty","marine","delicate"],
story:{en:"Fleur de sel sets as a thin crust on the surface of the pan on dry days with a light easterly, and the paludier lifts it with a flat wooden board called a lousse without ever touching the clay floor — grey salt is what is raked off the bottom afterwards. The marshes have been worked since the ninth century, and it is the clay that keeps the salt damp: it never fully dries.",
fr:"La fleur de sel prend en croûte fine à la surface de l’œillet les jours secs de vent d’est, et le paludier la lève à la lousse, une planche de bois plate, sans jamais toucher l’argile du fond — le gros sel gris est ce que l’on racle ensuite. Les marais sont travaillés depuis le IXe siècle et c’est l’argile qui explique son humidité : elle ne sèche jamais tout à fait."},
tip:{en:"Never cook with it and never put it in a liquid: the crunch is the whole product and it dissolves there into ordinary salinity. Add it once the plate is off the heat, and keep it in a closed pot — at about 5% moisture it cakes if left open and takes up whatever the kitchen smells of.",
fr:"Ne la cuisez jamais et ne la mettez pas dans un liquide : le croquant est tout le produit et il s’y dissout en salinité ordinaire. Ajoutez-la l’assiette hors du feu et gardez-la en pot fermé, à environ 5 % d’humidité elle prend en masse et se charge de toutes les odeurs de la cuisine."},
pairs:["butter","radish","tomato","turbot","saumon-fume","strawberry"],
svg:'<path class="f1 sf" d="M20 54h54v14q0 4-4 4H24q-4 0-4-4z"/><path class="s" d="M20 60h54"/><path class="f2 sf" d="M28 54q8-14 16 0z"/><path class="f3 sf" d="M50 49h20v5H50z"/><path class="s" d="M70 51l8-14"/><circle class="dot" cx="26" cy="48" r="1.8"/>'},

{id:"gari",cat:"condiments",name:{en:"Gari (pickled ginger)",fr:"Gari (gingembre mariné)"},latin:"Zingiber officinale",
origin:{en:"Japan",fr:"Japon"},season:[],
flavor:["sour","sweet","pungent","fresh"],
story:{en:"Gari is cut from young ginger lifted before the skin toughens, and the pink blush of a good jar comes from the rhizome's own pigments turning in the vinegar, not from dye. Most supermarket jars are coloured anyway, which is why they arrive a uniform cartoon pink.",
fr:"Le gari se taille dans du gingembre jeune, récolté avant que la peau ne durcisse : le rose des bons bocaux vient des pigments du rhizome qui virent au contact du vinaigre, non d’un colorant. La plupart des bocaux de supermarché sont teintés malgré tout, d’où ce rose uniforme de dessin animé."},
tip:{en:"If you make it, salt the sliced ginger for thirty minutes and squeeze it dry before the vinegar goes on, or the pickle turns watery within a week. Eat it between pieces of fish, never laid on top of one.",
fr:"Si vous le faites vous-même, salez les lamelles trente minutes et pressez-les bien avant d’ajouter le vinaigre, sinon le pickle rend son eau en une semaine. Mangez-le entre deux bouchées, jamais posé sur le poisson."},
pairs:["rice","nori","wasabi","soy-sauce","tuna","salmon","rice-vinegar"],
svg:'<path class="f2 sf" d="M26 56h44q-4 14-22 14T26 56z"/><path class="f1 sf" d="M34 54q6-16 16-16t-2 16z"/><path class="f1 sf" d="M42 54q8-14 18-12t-6 12z"/><path class="s" d="M38 44q6-4 10-2M50 46q6-4 8-2"/>'},

{id:"genmaicha",cat:"condiments",name:{en:"Genmaicha",fr:"Genmaicha"},latin:"Camellia sinensis / Oryza sativa",
origin:{en:"Kyoto, Japan",fr:"Kyoto, Japon"},season:[],
flavor:["toasty","nutty","grassy"],
story:{en:"The likeliest account puts it in a Kyoto tea shop in the 1920s, where the broken remains of kagami mochi — the New Year rice cakes — were roasted instead of thrown out and blended into cheap bancha. The rice was there to make the tea go further; the toasted-grain smell everyone now buys it for was an accident of thrift.",
fr:"La version la plus probable le situe dans une boutique de thé de Kyoto, dans les années 1920 : les débris du kagami-mochi du Nouvel An grillés plutôt que jetés, puis mêlés à un bancha bon marché. Le riz servait à faire durer le thé ; l’odeur de céréale grillée qu’on achète aujourd’hui n’était qu’un effet d’économie."},
tip:{en:"Brew it at 90 °C — near boiling, unlike any other Japanese green — for thirty seconds, or the rice tastes raw. It also works as a savoury liquid: infuse it strong and use it for half the dashi in a clear broth.",
fr:"Infusez-le à 90 °C — presque bouillant, contrairement à tout autre thé vert japonais — trente secondes, sinon le riz garde un goût cru. Il tient aussi comme liquide de cuisine : infusé serré, il remplace la moitié du dashi d’un bouillon clair."},
pairs:["rice","chestnut","sesame","mushroom","cream","salmon"],
svg:'<path class="f2 sf" d="M24 44h48c-2 18-12 26-24 26s-22-8-24-26z"/><path class="s" d="M20 44h56"/><ellipse class="f1 sf" cx="40" cy="54" rx="6" ry="3.5"/><ellipse class="f1 sf" cx="55" cy="58" rx="6" ry="3.5"/><path class="s" d="M32 61q6 4 12 2"/>'},

{id:"gochujang",cat:"condiments",name:{en:"Gochujang",fr:"Gochujang"},latin:"고추장",
origin:{en:"Korea",fr:"Corée"},season:[],
flavor:["hot","sweet","umami","salty"],
story:{en:"Chilli reached Korea only in the sixteenth century, yet within a hundred years this fermented paste of chilli, glutinous rice and soybean had become the country's defining flavour. Families kept earthenware jars of it on the roof to ferment in the sun.",
fr:"Le piment n’atteignit la Corée qu’au XVIe siècle, et pourtant en cent ans cette pâte fermentée de piment, riz gluant et soja était devenue la saveur qui définit le pays. Les familles gardaient les jarres de terre sur le toit pour fermenter au soleil."},
tip:{en:"It is sweet as well as hot, so it burns easily. Add it to a sauce off the heat or late, never at the start of a sear.",
fr:"Il est sucré autant que piquant, donc il brûle vite. Ajoutez-le hors du feu ou tard, jamais au début d’une saisie."},
pairs:["sesame-oil","garlic","soy-sauce","spring-onion","sesame","ginger","pork","rice"],
svg:'<path class="f1 sf" d="M34 72V44h28v28z"/><path class="s" d="M34 52h28"/><path class="s" d="M40 60q8 6 16 0"/>'},

{id:"sel-gris-guerande",cat:"condiments",name:{en:"Grey sea salt (sel gris)",fr:"Sel gris de Guérande"},latin:"Natrii chloridum marinum",
origin:{en:"Guérande, Brittany",fr:"Guérande, Bretagne"},season:[6,7,8,9],
flavor:["salty","briny","marine"],
story:{en:"The paludiers move seawater by gravity alone through clay basins laid out in the Middle Ages, and let sun and wind take it to saturation. Grey salt is what settles on the clay floor and is raked up damp; fleur de sel is only the thin crust that forms on the surface on a dry, windy afternoon.",
fr:"Les paludiers font circuler l’eau de mer par la seule gravité à travers des bassins d’argile aménagés dès le Moyen Âge, et laissent le soleil et le vent la mener à saturation. Le sel gris est celui qui se dépose sur le fond argileux et se rassemble humide ; la fleur de sel n’est que la mince croûte formée en surface les après-midi secs et ventés."},
tip:{en:"It stays damp and will not pass through a grinder — dissolve it for brines and pasta water, or crush it under a blade. Ten grams per litre of cooking water is the working dose and needs nothing added.",
fr:"Il reste humide et ne passera pas dans un moulin : dissolvez-le pour les saumures et l’eau des pâtes, ou écrasez-le sous la lame. Comptez 10 g par litre d’eau de cuisson, rien de plus."},
pairs:["potato","butter","cod","lamb","tomato","olive-oil","beef"],
svg:'<path class="f2 sf" d="M22 70q10-22 26-22t26 22z"/><path class="s" d="M30 62q8-6 16-2M40 54q6-4 12 0"/><path class="s" d="M64 30L48 52"/><path class="f3 sf" d="M60 22h16v6H60z"/>'},

{id:"gomme-de-guar",cat:"condiments",name:{en:"Guar gum",fr:"Gomme de guar"},latin:"Cyamopsis tetragonoloba",
origin:{en:"Rajasthan, India",fr:"Rajasthan, Inde"},season:[],
flavor:["mild","earthy"],
story:{en:"The powder is the milled endosperm of a drought-hardy desert bean grown mostly in Rajasthan, which supplies something like four-fifths of the world's guar. Its price is set less by kitchens than by oil fields — shale fracturing fluid runs on the same gum, and when American drilling boomed the bean briefly became India's largest agricultural export to the United States.",
fr:"La poudre est l’albumen broyé d’un haricot du désert résistant à la sécheresse, cultivé surtout au Rajasthan, qui fournit environ les quatre cinquièmes du guar mondial. Son cours dépend moins des cuisines que des champs pétroliers : la fracturation hydraulique emploie la même gomme, et l’essor du forage américain a brièvement fait de ce haricot la première exportation agricole indienne vers les États-Unis."},
tip:{en:"It hydrates in cold water with no heat at all and thickens up to eight times harder than starch, so weigh it at 0.1 to 0.3% of the liquid. Past that a sauce turns slick and slimy rather than thick, and the only repair is dilution.",
fr:"Elle s’hydrate à l’eau froide, sans aucune chauffe, et épaissit jusqu’à huit fois plus que l’amidon : pesez-la entre 0,1 et 0,3 % du liquide. Au-delà, la sauce devient glissante et baveuse plutôt qu’épaisse, et seule la dilution rattrape."},
pairs:["cream","yogurt","coconut-milk","vanilla","sugar","strawberry","buttermilk","dark-chocolate"],
svg:'<path class="f2 sf" d="M40 24q7 24 5 46-1 6-5 6t-5-6q2-22-4-45z"/><circle class="dot" cx="39" cy="40" r="2"/><circle class="dot" cx="40" cy="54" r="2"/><path class="f1 sf" d="M50 74q5-16 12-16t12 16z"/>'},

{id:"guk-ganjang",cat:"condiments",name:{en:"Guk-ganjang",fr:"Ganjang de soupe (guk-ganjang)"},latin:"Glycine max",
origin:{en:"Korea",fr:"Corée"},season:[],
flavor:["salty","umami","earthy"],
story:{en:"It is the liquid poured off the meju jar, the same ferment that leaves doenjang behind, and it contains no wheat at all — the wheat-brewed style Koreans call waeganjang came later, from Japan. Cooks still name this one joseon-ganjang, the Korean soy, and keep it for soups where the broth has to stay pale.",
fr:"C'est le liquide soutiré de la jarre de meju, la fermentation même qui laisse le doenjang au fond, et il ne contient aucun blé — le style brassé au blé, que les Coréens appellent waeganjang, est venu plus tard du Japon. Les cuisiniers nomment toujours celui-ci joseon-ganjang, la sauce soja coréenne, et le réservent aux soupes dont le bouillon doit rester clair."},
tip:{en:"It is far saltier than Japanese shoyu — start at a third of the volume you would use of ordinary soy sauce and taste before adding more. It seasons, it should not colour: if the broth is going brown you have already used too much.",
fr:"Il sale bien plus que le shoyu japonais : partez du tiers du volume que vous mettriez de sauce soja ordinaire et goûtez avant d'en rajouter. Il assaisonne, il ne doit pas colorer : si le bouillon brunit, vous en avez déjà mis trop."},
pairs:["beef","spinach","garlic","sesame-oil","doenjang","daikon","egg","kombu"],
svg:'<path class="f1 sf" d="M30 52q0-13 12-13t12 13q0 11-12 11t-12-11z"/><path class="s" d="M54 46 71 31"/><path class="s" d="M34 48q8 4 16 0"/><path class="s" d="M38 62v7M46 63v9"/>'},

{id:"gyokuro",cat:"condiments",name:{en:"Gyokuro",fr:"Gyokuro"},latin:"Camellia sinensis var. sinensis",
origin:{en:"Uji, Kyoto prefecture",fr:"Uji, préfecture de Kyoto"},season:[4,5],
flavor:["umami","sweet","marine"],
story:{en:"The bushes are covered for roughly three weeks before picking. Starved of light the leaf stops building the bitter catechins and stockpiles theanine instead, which is why a cup of gyokuro reads closer to a shellfish stock than to tea.",
fr:"On couvre les théiers une vingtaine de jours avant la cueillette. Privée de lumière, la feuille cesse de fabriquer les catéchines amères et accumule de la théanine : une tasse de gyokuro se lit alors plus comme un fumet de coquillages que comme un thé."},
tip:{en:"Brew at 50–60 °C and never hotter — above that the catechins come out and bury the umami. Two minutes, a heavy dose of leaf, very little water; keep the spent leaves, they are edible dressed with soy and vinegar.",
fr:"Infusez à 50–60 °C, jamais plus chaud : au-delà, les catéchines sortent et enterrent l’umami. Deux minutes, beaucoup de feuilles, très peu d’eau — et gardez les feuilles infusées, elles se mangent, assaisonnées sauce soja et vinaigre."},
pairs:["rice","scallop","sea-bream","nori","egg","kombu"],
svg:'<path class="f2 sf" d="M30 47h34c2 9-3 21-13 23H43c-10-2-15-14-13-23z"/><path class="s" d="M27 47h40"/><path class="f1 sf" d="M41 39h14c0 4-3 7-7 7s-7-3-7-7z"/><path class="f2 sf" d="M64 51h13l-3 7H64z"/><path class="f2 sf" d="M30 51l-11-4 3 8z"/>'},

{id:"harissa",cat:"condiments",name:{en:"Harissa",fr:"Harissa"},latin:"هريسة",
origin:{en:"Tunisia",fr:"Tunisie"},season:[],
flavor:["hot","smoky","earthy","pungent"],
story:{en:"Tunisia's national condiment, and the chillies in it arrived with Ottoman traders after the Columbian exchange. The best is from Nabeul, where the peppers are sun-dried on rooftops before being ground with caraway, coriander and garlic.",
fr:"Le condiment national tunisien, dont les piments sont arrivés avec les marchands ottomans après l’échange colombien. La meilleure vient de Nabeul, où les piments sèchent au soleil sur les toits avant d’être broyés au carvi, à la coriandre et à l’ail."},
tip:{en:"Caraway is what makes it harissa rather than chilli paste. If yours has none, it is missing the defining note.",
fr:"C’est le carvi qui en fait une harissa plutôt qu’une purée de piment. Si la vôtre n’en contient pas, il lui manque la note qui la définit."},
pairs:["caraway","garlic","olive-oil","cumin","lamb","tomato","chickpeas","lemon"],
svg:'<path class="f1 sf" d="M36 72V46h24v26z"/><path class="s" d="M36 54h24"/><path class="s" d="M42 62l4 4 4-4 4 4"/>'},

{id:"hatcho-miso",cat:"condiments",name:{en:"Hatchō miso",fr:"Hatchō miso"},latin:"Glycine max",
origin:{en:"Okazaki, Aichi",fr:"Okazaki, préfecture d'Aichi"},season:[],
flavor:["umami","bitter","rich"],
story:{en:"Hatchō is a place — eight chō from Okazaki castle — where two houses still ferment nothing but soybeans, salt and water, with no rice or barley koji in the vat at all. Each cedar barrel is weighted with river stones stacked by hand into a cone of about three tonnes, and it has to stand without mortar through two full summers.",
fr:"Hatchō est un lieu — à huit chō du château d'Okazaki — où deux maisons ne font encore fermenter que du soja, du sel et de l'eau, sans le moindre koji de riz ou d'orge dans la cuve. Chaque foudre de cèdre est lesté de galets de rivière empilés à la main en un cône d'environ trois tonnes, qui doit tenir sans mortier pendant deux étés entiers."},
tip:{en:"Use half what a recipe asks of rice miso; it is denser and far more astringent. Slake it through a strainer into hot broth and never let it boil — at a rolling boil the aroma is gone inside a minute.",
fr:"Employez la moitié de ce qu'une recette demande de miso de riz : il est plus dense et bien plus astringent. Délayez-le au travers d'une passoire dans le bouillon chaud et ne le faites jamais bouillir : à gros bouillons, l'arôme a disparu en moins d'une minute."},
pairs:["eggplant","daikon","pork","hon-mirin","konnyaku","sugar","kombu","dark-chocolate"],
svg:'<path class="f2 sf" d="M28 48h40v22q0 6-6 6H34q-6 0-6-6z"/><path class="s" d="M36 48v28M48 48v28M60 48v28"/><path class="f3 sf" d="M34 46q4-6 14-6t14 6z"/><circle class="f3 sf" cx="48" cy="32" r="5"/><circle class="f1 sf" cx="40" cy="38" r="4.5"/><circle class="f1 sf" cx="56" cy="38" r="4.5"/>'},

{id:"hon-mirin",cat:"condiments",name:{en:"Hon-mirin",fr:"Mirin (hon-mirin)"},latin:"Oryza sativa var. glutinosa",
origin:{en:"Japan",fr:"Japon"},season:[],
flavor:["sweet","mild","rich"],
story:{en:"Real mirin is a liquor: glutinous rice and koji left to sweeten in shochu until the whole thing sits at about 14 % alcohol, and Japan taxes it as one. That tax is why supermarket shelves carry mirin-fu chomiryo, a sweetened imitation held under one per cent, and why the genuine bottle stands with the sake.",
fr:"Le vrai mirin est un alcool : riz gluant et koji laissés à sucrer dans le shochu jusqu'à environ 14 % vol., et le Japon le taxe comme tel. C'est cette taxe qui explique le mirin-fu chomiryo des rayons de supermarché, une imitation sucrée maintenue sous 1 %, et pourquoi la vraie bouteille se range avec les sakés."},
tip:{en:"Boil it thirty seconds to burn the alcohol off before it goes into a dressing that will not be cooked further. In a glaze it goes in last: the glucose colours fast and will be bitter before the fish is done if the pan is above medium.",
fr:"Faites-le bouillir trente secondes pour brûler l'alcool avant de l'employer dans une sauce qui ne cuira plus. Dans un laquage, il entre en dernier : le glucose colore vite et sera amer avant que le poisson ne soit cuit si la poêle dépasse le feu moyen."},
pairs:["soy-sauce","junmai-sake","sugar","eel","chicken","miso","dried-shiitake-donko","kombu"],
svg:'<path class="f1 sf" d="M44 26h8v8q10 8 10 22t-14 20-14-20 10-22z"/><path class="s" d="M43 31h10"/><path class="f2 sf" d="M61 65h15q-1 11-7.5 11T61 65z"/><path class="s" d="M40 56q8 4 16 0"/>'},

{id:"honey-vinegar",cat:"condiments",name:{en:"Honey vinegar",fr:"Vinaigre de miel"},latin:"Acetum mellis",
origin:{en:"Northern Europe",fr:"Europe du Nord"},season:[],
flavor:["sour","honeyed","floral","mild"],
story:{en:"Vinegar only forms on something already alcoholic, so this one begins as mead: yeast first, acetobacter second, two fermentations where wine vinegar needs one. The detour costs it bite — most bottles sit near 5% acidity against a wine vinegar's 7.",
fr:"Le vinaigre ne se forme que sur un liquide déjà alcoolisé : celui-ci part donc d’un hydromel, la levure d’abord, l’acétobacter ensuite, deux fermentations là où le vinaigre de vin n’en demande qu’une. Ce détour lui coûte du mordant : la plupart des bouteilles tournent autour de 5 % d’acidité, contre 7 pour un vinaigre de vin."},
tip:{en:"Deglaze a roast chicken pan with it and mount with cold butter — it needs no sugar added, where a wine vinegar would. One part vinegar to three of pan juices.",
fr:"Déglacez-en un plat de volaille rôtie et montez au beurre froid : il n’a besoin d’aucun sucre, contrairement au vinaigre de vin. Comptez une part de vinaigre pour trois de jus."},
pairs:["chicken","butter","shallot","honey","carrot","duck","mustard"],
svg:'<path class="f1 sf" d="M42 22h12v8q8 6 8 16v26q0 4-4 4H38q-4 0-4-4V46q0-10 8-16z"/><path class="s" d="M34 56h28"/><path class="f2 sf" d="M48 55l7 4v8l-7 4-7-4v-8z"/>'},

{id:"kala-namak",cat:"condiments",name:{en:"Kala namak (Indian black salt)",fr:"Kala namak (sel noir de l’Himalaya)"},latin:"Halitum",
origin:{en:"North India & Pakistan",fr:"Inde du Nord & Pakistan"},season:[],
flavor:["salty","pungent","earthy"],
story:{en:"Raw rock salt is sealed into a clay kiln with charcoal and harad seeds and fired for hours; the reaction leaves iron sulphides behind and the lumps come out violet-black. Ground, they turn pink-grey and smell unmistakably of boiled egg yolk — hydrogen sulphide, the same compound.",
fr:"Le sel gemme brut est enfermé dans un four d’argile avec du charbon et des graines de harad, puis cuit des heures : la réaction laisse des sulfures de fer et les blocs sortent noir violacé. Moulus, ils deviennent rose gris et sentent sans équivoque le jaune d’œuf dur — de l’hydrogène sulfuré, le même composé."},
tip:{en:"Add it off the heat at the end: the sulphur volatiles that carry the egg note leave within a minute of boiling. A quarter teaspoon is enough to make scrambled tofu read as egg.",
fr:"Ajoutez-le hors du feu, en fin de course : les composés soufrés qui portent la note d’œuf s’échappent en une minute d’ébullition. Un quart de cuillère à café suffit à faire passer un tofu brouillé pour des œufs."},
pairs:["chickpeas","cucumber","lime","cilantro","cumin","yogurt","tamarind-paste","silken-tofu"],
svg:'<path class="f1 sf" d="M28 54h40q-2 18-20 18T28 54z"/><path class="f3 sf" d="M34 54q6-16 14-16t14 16z"/><path class="s" d="M40 48q8-4 16 0"/><circle class="dot" cx="72" cy="66" r="2"/>'},

{id:"agar-agar-kanten",cat:"condiments",name:{en:"Kanten (agar-agar)",fr:"Agar-agar (kanten)"},latin:"Gelidium amansii",
origin:{en:"Japan, from red algae",fr:"Japon, à partir d'algues rouges"},season:[],
flavor:["mild","marine"],
story:{en:"The story goes that a Kyoto innkeeper set out leftover tokoroten jelly on a winter night in the 1650s and found it freeze-dried by morning, which is still exactly how kanten is made. Two centuries later Fanny Hesse suggested it to Robert Koch's laboratory as a culture medium that would not melt in a warm incubator, and bacteriology has grown on it ever since.",
fr:"L'histoire veut qu'un aubergiste de Kyoto ait laissé dehors, une nuit d'hiver des années 1650, un reste de gelée de tokoroten et l'ait retrouvé lyophilisé au matin — c'est encore exactement ainsi que se fabrique le kanten. Deux siècles plus tard, Fanny Hesse le suggérait au laboratoire de Robert Koch comme milieu de culture qui ne fondrait pas dans une étuve tiède, et la bactériologie pousse dessus depuis."},
tip:{en:"It has to reach a full rolling boil for two minutes or it never hydrates and never sets. Count on about 1 g of powder per 150 ml for a set you can slice; it firms at around 40 °C and will not melt again below 85 °C, so it holds on a warm plate where gelatine would already be a puddle.",
fr:"Il doit atteindre une pleine ébullition pendant deux minutes, faute de quoi il ne s'hydrate pas et ne prend jamais. Comptez environ 1 g de poudre pour 150 ml pour une gelée que l'on tranche ; elle prend vers 40 °C et ne refond qu'à partir de 85 °C, si bien qu'elle tient sur une assiette tiède où la gélatine serait déjà une flaque."},
pairs:["sugar","adzuki","matcha","coconut-milk","kokuto","lemon","honey"],
svg:'<path class="f1 sf" d="M28 44h16v28H28z"/><path class="s" d="M33 44v28M38.5 44v28"/><path class="f2 sf" d="M52 52h18v20H52z"/><path class="s" d="M52 52 58 46h18l-6 6M70 52l6-6v20l-6 6"/>'},

{id:"karashi",cat:"condiments",name:{en:"Karashi (Japanese mustard)",fr:"Karashi (moutarde japonaise)"},latin:"Brassica juncea",
origin:{en:"Japan",fr:"Japon"},season:[],
flavor:["pungent","hot","bitter"],
story:{en:"Karashi is brown mustard seed ground fine and nothing else — no vinegar, no wine, no salt — so it makes its own heat only once water lets the enzyme meet its precursor. Kumamoto packs it into the holes of a lotus root and fries the slice, a dish the story goes was devised to feed an ailing lord.",
fr:"Le karashi n’est que de la graine de moutarde brune broyée fin — ni vinaigre, ni vin, ni sel — de sorte qu’il ne fabrique son piquant qu’à l’eau, quand l’enzyme rencontre son précurseur. Kumamoto en garnit les trous d’une racine de lotus avant de la frire, un plat qu’on dit inventé pour nourrir un seigneur de santé fragile."},
tip:{en:"Mix the powder with water at body temperature, never hot, and let it stand ten minutes — boiling water kills the enzyme and leaves bitterness with no heat. It fades within half an hour, so mix it as you serve.",
fr:"Délayez la poudre à l’eau tiède, jamais chaude, et laissez reposer dix minutes : l’eau bouillante tue l’enzyme et il ne reste que de l’amertume. Le piquant retombe en une demi-heure, préparez-le au moment de servir."},
pairs:["pork","lotus-root","soy-sauce","miso","egg","shrimp","napa-cabbage"],
svg:'<path class="f1 sf" d="M38 34h20v34l-20 8z"/><path class="f3 sf" d="M44 22h8v12h-8z"/><path class="s" d="M40 44h16"/><path class="f2 sf" d="M48 14q4 4 4 8h-8q0-4 4-8z"/>'},

{id:"katsuobushi",cat:"condiments",rare:true,name:{en:"Katsuobushi",fr:"Katsuobushi"},latin:"Katsuwonus pelamis (dried)",
origin:{en:"Japan",fr:"Japon"},season:[],
flavor:["umami","smoky","marine","toasty"],
story:{en:"Bonito simmered, smoked for weeks and dried with a noble mould until it becomes the hardest food on Earth — a fillet that rings like wood. Shaved into rosy petals, its inosinate meets kombu’s glutamate in dashi, a synergy that multiplies perceived umami nearly eightfold: broth as chemistry lesson.",
fr:"Une bonite pochée, fumée des semaines et séchée sous une noble moisissure jusqu’à devenir l’aliment le plus dur du monde — un filet qui sonne comme du bois. Rabotée en pétales rosés, son inosinate rencontre le glutamate du kombu dans le dashi, une synergie qui multiplie l’umami perçu par près de huit : le bouillon comme leçon de chimie."},
tip:{en:"Buy the flakes in small bags — the perfume fades fast once opened. A handful over hot rice with soy sauce is Japan’s simplest luxury; watch the petals dance in the steam.",
fr:"Achetez les copeaux en petits sachets — le parfum s’évente vite. Une poignée sur un riz chaud avec de la sauce soja est le luxe le plus simple du Japon ; regardez les pétales danser dans la vapeur."},
pairs:["kombu","rice","soy-sauce","egg","shiitake"],
svg:'<path class="f2 sf" d="M30 56q14-10 30-6l8-4-1 6 1 6-8-4q-16 4-30 2z"/><path class="f1 sf" d="M36 40q8-4 14 0l-2 6q-6-3-10 0z"/>'},

{id:"kecap-manis",cat:"condiments",name:{en:"Kecap manis",fr:"Kecap manis"},latin:"Glycine max",
origin:{en:"Java, Indonesia",fr:"Java, Indonésie"},season:[],
flavor:["sweet","salty","umami"],
story:{en:"The word travelled: Hokkien kê-tsiap, a fermented fish brine, became Malay kecap and then English ketchup, so a bottle of tomato sauce carries an Indonesian soy sauce's name. Kecap manis itself is closer to syrup than sauce — palm sugar can be half its weight.",
fr:"Le mot a voyagé : le kê-tsiap hokkien, une saumure de poisson fermenté, est devenu le kecap malais puis le ketchup anglais — la sauce tomate porte donc le nom d’une sauce soja indonésienne. Le kecap manis, lui, tient du sirop : le sucre de palme peut en représenter la moitié du poids."},
tip:{en:"It scorches — brush it on in the last two minutes of grilling, not before, or the sugar blackens while the meat is still raw. Cut it with lime juice to stop the sweetness flattening everything.",
fr:"Il brûle : badigeonnez-en dans les deux dernières minutes de grillade, pas avant, sinon le sucre noircit sur une viande encore crue. Coupez-le de jus de citron vert pour que le sucré n’écrase pas tout."},
pairs:["palm-sugar","garlic","chili","lime","shallot","peanut","chicken","soy-sauce"],
svg:'<path class="f3 sf" d="M44 20h8v14q8 6 8 18v22q0 4-4 4H40q-4 0-4-4V52q0-12 8-18z"/><path class="f1 sf" d="M36 58h24v18q0 4-4 4H40q-4 0-4-4z"/><path class="s" d="M44 20h8M40 48h16"/><circle class="dot" cx="48" cy="14" r="3"/>'},

{id:"kimchi",cat:"condiments",name:{en:"Kimchi",fr:"Kimchi"},latin:"김치",
origin:{en:"Korea",fr:"Corée"},season:[],
flavor:["sour","hot","umami","salty"],
story:{en:"Kimjang, the communal making of winter kimchi, is on the UNESCO intangible heritage list — whole neighbourhoods still gather in late autumn to salt and pack hundreds of cabbages at once. Korean households often keep a second refrigerator for it alone.",
fr:"Le kimjang, fabrication collective du kimchi d’hiver, figure au patrimoine immatériel de l’UNESCO — des quartiers entiers se réunissent encore à la fin de l’automne pour saler et empoter des centaines de choux d’un coup. Les foyers coréens gardent souvent un second réfrigérateur rien que pour lui."},
tip:{en:"Old, sour kimchi is not spoiled — it is the cooking grade. Young kimchi is for eating raw; the sour one is for stews and pancakes.",
fr:"Un kimchi vieux et acide n’est pas gâté — c’est la qualité à cuire. Le jeune se mange cru ; l’acide va aux ragoûts et aux galettes."},
pairs:["pork","rice","sesame-oil","spring-onion","egg","garlic","gochujang","soy-sauce"],
svg:'<path class="f1 sf" d="M32 70q4-24 16-24t16 24z"/><path class="s" d="M40 56q8 4 16 0M38 64q10 4 20 0"/>'},

{id:"glucomannane-de-konjac",cat:"condiments",name:{en:"Konjac glucomannan",fr:"Glucomannane de konjac"},latin:"Amorphophallus konjac",
origin:{en:"Japan & Yunnan, China",fr:"Japon & Yunnan, Chine"},season:[],
flavor:["earthy","mild"],
story:{en:"The flour is milled from the corm of a woodland aroid whose flower smells of carrion, and it is said to have reached Japan from China around the sixth century as a medicine rather than a food. It is very nearly pure fibre: the gel it sets carries almost no calories, which is how the same powder ends up in slimming noodles and in the konnyaku block sold beside the tofu.",
fr:"La farine est tirée du corme d’une aracée forestière dont la fleur sent la charogne ; elle serait arrivée de Chine au Japon vers le VIe siècle, comme remède avant d’être un aliment. C’est presque uniquement de la fibre : le gel qu’elle forme n’apporte quasiment pas de calories, d’où la même poudre dans les nouilles minceur et dans le bloc de konnyaku vendu à côté du tofu."},
tip:{en:"It needs alkali as well as heat: whisk 2 g into 200 ml of water, let it swell half an hour, stir in a pinch of slaked lime or sodium carbonate, then hold it above 70°C. The gel that forms will never melt again, so decide the shape before you set it.",
fr:"Il lui faut de l’alcalin autant que de la chaleur : fouettez 2 g dans 200 ml d’eau, laissez gonfler une demi-heure, ajoutez une pincée de chaux éteinte ou de carbonate de sodium, puis maintenez au-dessus de 70 °C. Le gel obtenu ne refondra jamais : choisissez la forme avant de le prendre."},
pairs:["soy-sauce","kombu","miso","sesame","ginger","chili","katsuobushi"],
svg:'<circle class="f2 sf" cx="48" cy="54" r="18"/><path class="f1 sf" d="M48 36a18 18 0 0116 10 40 40 0 01-32 0 18 18 0 0116-10z"/><path class="s" d="M48 36v-8M42 30l-3-6M55 30l4-6"/><path class="s" d="M38 62q10 5 21 0"/>'},

{id:"kukicha",cat:"condiments",name:{en:"Kukicha",fr:"Kukicha"},latin:"Camellia sinensis var. sinensis",
origin:{en:"Japan, from the tea sorting table",fr:"Japon, issu de la table de triage"},season:[],
flavor:["nutty","creamy","mild"],
story:{en:"Kukicha is what the sorting machines pull aside: stems and leaf ribs separated from the blade when sencha or gyokuro is graded. Caffeine concentrates in the young buds and barely reaches the stalks, so a tea made from the offcuts brews mild enough for a child and round enough to take milk.",
fr:"Le kukicha, c’est ce que la trieuse écarte : tiges et nervures séparées du limbe au moment de classer le sencha ou le gyokuro. La caféine se concentre dans les jeunes bourgeons et n’atteint guère les rameaux — un thé fait des chutes infuse assez doux pour un enfant et assez rond pour accepter le lait."},
tip:{en:"Stems need heat the blade cannot take: 80 °C and two full minutes, otherwise the cup comes out thin and tastes of nothing. Karigane — the same cut taken off gyokuro bushes — is the version worth the extra money.",
fr:"Les tiges demandent une chaleur que le limbe ne supporte pas : 80 °C et deux bonnes minutes, sans quoi la tasse reste creuse et sans goût. Le karigane — la même coupe, prise sur des théiers de gyokuro — est la version qui vaut le surcoût."},
pairs:["rice","chestnut","honey","white-chocolate","hazelnut","pear"],
svg:'<path class="s" d="M26 74 45 24M35 76 51 22M45 78 59 26M55 74 67 30"/><path class="s" d="M41 40l-9-7M53 36l9-8M46 60l-11 4"/><path class="f2 sf" d="M32 54h32a4 4 0 0 1 0 8H32a4 4 0 0 1 0-8z"/>'},

{id:"kurozu",cat:"condiments",name:{en:"Kurozu",fr:"Vinaigre noir japonais (kurozu)"},latin:"Oryza sativa",
origin:{en:"Fukuyama, Kagoshima",fr:"Fukuyama, Kagoshima"},season:[],
flavor:["sour","umami","nutty"],
story:{en:"Unpolished rice, koji and water go into one earthenware jar standing in an open field, and all three stages — saccharification, alcohol, then acetic acid — run in that single vessel over one to three years. The jars have stood in rows at Fukuyama in Kagoshima since about 1800, worked without lids, pumps or any transfer between tanks.",
fr:"Riz complet, koji et eau entrent dans une seule jarre de terre posée en plein champ, et les trois étapes — saccharification, alcool, puis acide acétique — s'y déroulent dans ce même récipient pendant un à trois ans. Les jarres s'alignent à Fukuyama, dans le Kagoshima, depuis 1800 environ, menées sans couvercle, sans pompe et sans aucun transvasement."},
tip:{en:"It is rounder and far less aggressive than rice vinegar, so use it undiluted where you would otherwise cut a vinegar with water. A spoonful stirred into a pork stir-fry at the end reads as depth rather than as acidity.",
fr:"Il est plus rond et bien moins agressif que le vinaigre de riz : employez-le pur là où vous couperiez un vinaigre à l'eau. Une cuillerée ajoutée en fin de cuisson dans un sauté de porc se lit comme de la profondeur, non comme de l'acidité."},
pairs:["honey","ginger","soy-sauce","pork","cucumber","sesame-oil","rice","hon-mirin"],
svg:'<path class="f3 sf" d="M42 26h12l-2 8q14 8 14 24t-18 20-18-20 14-24z"/><path class="s" d="M39 26h18"/><path class="s" d="M34 56q14 6 28 0M35 64q13 5 26 0"/>'},

{id:"gomme-de-caroube",cat:"condiments",name:{en:"Locust bean gum",fr:"Gomme de caroube"},latin:"Ceratonia siliqua",
origin:{en:"Mediterranean carob groves",fr:"Caroubières méditerranéennes"},season:[],
flavor:["mild","nutty"],
story:{en:"Only the endosperm of the carob seed becomes gum — husk and germ are milled away first. The seeds are so nearly identical in weight that jewellers, the story goes, used them as their reference grain, which is where the carat took its name; the roasted pod sold as a cocoa substitute is a different product entirely.",
fr:"Seul l’albumen de la graine de caroube devient gomme : l’enveloppe et le germe sont écartés au broyage. Les graines sont si régulières de poids que les joailliers, dit-on, s’en servaient de référence — d’où le mot carat ; la gousse grillée vendue comme succédané de cacao est, elle, un tout autre produit."},
tip:{en:"It will not hydrate cold: bring the liquid to 85°C for a minute or the gum stays gritty and thin. Alongside kappa carrageenan it turns a brittle gel elastic and stops it weeping, which is why it sits in nearly every industrial ice cream.",
fr:"Elle ne s’hydrate pas à froid : portez le liquide à 85 °C une minute, sinon la gomme reste sableuse et sans corps. Associée au carraghénane kappa, elle assouplit un gel cassant et l’empêche de rendre son eau — c’est pour cela qu’elle figure dans presque toutes les glaces industrielles."},
pairs:["cream","vanilla","coconut-milk","yogurt","sugar","dark-chocolate","hazelnut","honey"],
svg:'<path class="f3 sf" d="M22 40q14-10 28-2t24 8q-8 8-24 2T22 40z"/><path class="s" d="M26 42q14-6 26 0t20 4"/><ellipse class="f1 sf" cx="38" cy="68" rx="7" ry="5"/><ellipse class="f1 sf" cx="56" cy="70" rx="7" ry="5"/>'},

{id:"malt-vinegar",cat:"condiments",name:{en:"Malt vinegar",fr:"Vinaigre de malt"},latin:"Acetum brasii",
origin:{en:"Britain",fr:"Grande-Bretagne"},season:[],
flavor:["sour","toasty","earthy","tangy"],
story:{en:"Made from soured ale rather than wine, in a country that never had vineyards to spare. It is the one vinegar built for fried food — the malt sweetness stands up to hot fat where a wine vinegar just tastes thin.",
fr:"Fait de bière tournée plutôt que de vin, dans un pays qui n’avait pas de vignes à perdre. C’est le seul vinaigre conçu pour la friture — la douceur maltée tient contre le gras chaud là où un vinaigre de vin paraît maigre."},
tip:{en:"Shake it on hot chips the moment they leave the fryer, before they cool. Steam carries it into the potato.",
fr:"Aspergez-en les frites brûlantes dès la sortie du bain, avant refroidissement. La vapeur l’emporte dans la pomme de terre."},
pairs:["potato","cod","onion","black-pepper","butter","egg","mustard","beef"],
svg:'<path class="f1 sf" d="M40 76V40h16v36z"/><path class="s" d="M40 48h16"/><path class="f2 sf" d="M44 36V24h8v12z"/>'},

{id:"miso",cat:"condiments",name:{en:"Miso",fr:"Miso"},latin:"Fermented soybean paste",
origin:{en:"Japan",fr:"Japon"},season:[],
flavor:["umami","salty","sweet","earthy"],
story:{en:"Samurai marched on miso — it travelled as dry rations and dissolved into instant soup. Every region and family had its own: white and sweet in Kyoto, dark and fierce in the north. “Handmade miso tastes of the maker’s hands,” the saying goes.",
fr:"Les samouraïs marchaient au miso — il voyageait en ration sèche et se dissolvait en soupe instantanée. Chaque région, chaque famille avait le sien : blanc et doux à Kyoto, sombre et puissant au nord. « Le miso maison a le goût des mains qui l’ont fait », dit le proverbe."},
tip:{en:"Never boil it — heat kills its living aromas; whisk it in at the end. Beyond soup, a spoonful transforms butter, glazes for eggplant, even caramel.",
fr:"Ne le faites jamais bouillir — la chaleur tue ses arômes vivants ; incorporez-le en fin de cuisson. Au-delà de la soupe, une cuillerée transforme un beurre, un glaçage d’aubergine, même un caramel."},
pairs:["eggplant","sesame","shiitake","ginger","salmon","butter","honey"],
svg:'<path class="f1 sf" d="M32 52h32v6q0 14-16 14T32 58z"/><path class="f2 sf" d="M36 52q0-8 12-8t12 8z"/><path class="s" d="M60 44l10-12"/>'},

{id:"moscatel-vinegar",cat:"condiments",name:{en:"Moscatel vinegar",fr:"Vinaigre de Moscatel"},latin:"Vitis vinifera",
origin:{en:"Andalusia, Spain",fr:"Andalousie, Espagne"},season:[],
flavor:["sour","sweet","floral"],
story:{en:"Muscat of Alexandria is among the oldest grapes still farmed, and in Andalusia its wine is sweet enough that vinegar made from it keeps a residue of sugar the acetobacter never reaches. The sherry vinegar rules give it a category of its own, aged in the same soleras as the rest.",
fr:"Le muscat d’Alexandrie est l’un des plus anciens cépages encore cultivés, et en Andalousie son vin est assez sucré pour que le vinaigre garde un reste de sucre que l’acétobacter n’atteint jamais. La réglementation du vinaigre de Xérès lui réserve sa propre catégorie, élevée dans les mêmes soleras que le reste."},
tip:{en:"It carries sugar, so it glazes: reduce it by half in the pan after searing foie gras or duck and it naps on its own. In a vinaigrette use less oil than usual — three to one is plenty.",
fr:"Il contient du sucre, donc il glace : réduit de moitié dans la poêle après un foie gras ou un magret, il nappe tout seul. En vinaigrette, allégez l’huile — trois pour un suffit."},
pairs:["foie-gras","duck","strawberry","olive-oil","shallot","blue-cheese","peach","endive"],
svg:'<path class="f2 sf" d="M42 30h12v10l4 8v28q0 4-4 4H42q-4 0-4-4V48l4-8z"/><path class="s" d="M38 56h20"/><circle class="f1 sf" cx="66" cy="52" r="5"/><circle class="f1 sf" cx="70" cy="62" r="5"/><circle class="f1 sf" cx="60" cy="62" r="5"/><path class="s" d="M66 46v-6"/>'},

{id:"moshio-salt",cat:"condiments",name:{en:"Moshio seaweed salt",fr:"Sel d’algues moshio"},latin:"Sargassum fulvellum",
origin:{en:"Kamagari, Seto Inland Sea",fr:"Kamagari, mer intérieure de Seto"},season:[],
flavor:["salty","marine","umami"],
story:{en:"Before Japan had salt pans it had moshio: seawater steeped with hondawara seaweed, then boiled down in clay pots. Excavated shards around the Seto Inland Sea let salt-makers on Kamagari island rebuild the method in the 1980s, and the beige crystals carry the seaweed's glutamate along with its salt.",
fr:"Avant les marais salants, le Japon avait le moshio : de l’eau de mer infusée d’algue hondawara, puis réduite dans des jarres de terre. Des tessons exhumés en mer intérieure de Seto ont permis aux sauniers de l’île de Kamagari de reconstituer la méthode dans les années 1980, et les cristaux beiges portent le glutamate de l’algue autant que son sel."},
tip:{en:"Use it where soy sauce would darken the plate — a pinch on white sashimi, tempura or chilled tofu supplies the salt and the savour together. Do not dissolve it into a stock; nothing survives that a cheaper salt would not do.",
fr:"Employez-le là où la sauce soja noircirait l’assiette : une pincée sur un sashimi blanc, une tempura ou un tofu froid apporte le sel et le goût. Ne le dissolvez pas dans un bouillon, rien n’y survit qu’un sel ordinaire ne ferait aussi bien."},
pairs:["silken-tofu","sea-bream","squid","rice","egg","cucumber","scallop","sea-urchin"],
svg:'<path class="f1 sf" d="M28 56l6 18h28l6-18z"/><path class="f2 sf" d="M36 56q6-14 12-14t12 14z"/><path class="s" d="M28 56h40"/><path class="s" d="M66 26q-6 10-4 20M66 26q-8 2-8 8M66 26q0 10 6 12"/>'},

{id:"mostarda-di-cremona",cat:"condiments",name:{en:"Mostarda di Cremona",fr:"Mostarda di Cremona (fruits confits à la moutarde)"},latin:"Mostum ardens",
origin:{en:"Cremona, Lombardy",fr:"Crémone, Lombardie"},season:[],
flavor:["sweet","hot","fruity","pungent"],
story:{en:"The name is older than mustard the condiment: medieval mostum ardens, burning must, was grape must spiked with ground seed to stop it fermenting. Cremona kept the fruit, swapped the must for sugar syrup, and adds mustard essence drop by drop — a few drops flavour a whole jar.",
fr:"Le nom précède la moutarde condiment : le mostum ardens médiéval, le moût brûlant, était du moût de raisin relevé de graine broyée pour l’empêcher de fermenter. Crémone a gardé les fruits, remplacé le moût par un sirop de sucre, et ajoute l’essence de moutarde goutte à goutte — quelques gouttes parfument un bocal entier."},
tip:{en:"Serve it in small pieces beside bollito misto or a hard aged cheese, never spread — the heat is volatile and arrives late, in the nose rather than the mouth. Two candied cherries per plate is a portion.",
fr:"Servez-la en petits morceaux à côté d’un bollito misto ou d’un fromage vieux, jamais étalée : le piquant est volatil et arrive en retard, dans le nez plutôt qu’en bouche. Deux cerises confites par assiette font une portion."},
pairs:["parmesan","gorgonzola-piccante","quince","pear","beef","pork","grana-padano","mustard-seed"],
svg:'<path class="f1 sf" d="M32 34h32v40q0 4-4 4H36q-4 0-4-4z"/><path class="f3 sf" d="M30 26h36v8H30z"/><path class="f2 sf" d="M44 46q4 0 4 4t4 8-4 8-8-4 0-12 4-4z"/><circle class="f2 sf" cx="57" cy="64" r="6"/><path class="s" d="M57 58v-6"/>'},

{id:"mugi-miso",cat:"condiments",name:{en:"Mugi miso",fr:"Miso d’orge (mugi)"},latin:"Hordeum vulgare (fermented)",
origin:{en:"Kyushu & Shikoku",fr:"Kyushu & Shikoku"},season:[],
flavor:["umami","sweet","earthy","toasty"],
story:{en:"Barley koji instead of rice makes the country miso of Kyushu, Shikoku and the north of Kanto — barley grew where the rice went to the tax collector, so farmhouses fermented what they kept. The husks stay visible in the paste and the sweetness reads bready rather than clean.",
fr:"Un koji d’orge au lieu du riz : c’est le miso paysan de Kyushu, de Shikoku et du nord du Kanto, où l’orge poussait quand le riz partait à l’impôt. Les enveloppes restent visibles dans la pâte et la douceur tire vers le pain plutôt que vers le net."},
tip:{en:"Dissolve it in a ladle of hot broth off the heat and never let it boil — the aroma is gone inside a minute. It is the miso for pork and root vegetables; pass it through a strainer if you want a clear soup rather than a grainy one.",
fr:"Délayez-le dans une louche de bouillon chaud hors du feu et ne le faites jamais bouillir : l’arôme part en moins d’une minute. C’est le miso du porc et des racines ; passez-le au chinois si vous voulez une soupe claire plutôt que grenue."},
pairs:["pork","daikon","negi","burdock-root","sweet-potato","kome-koji","silken-tofu"],
svg:'<path class="f2 sf" d="M32 36h32l-4 38H36z"/><path class="s" d="M33 48h30M34 62h28"/><ellipse class="f1 sf" cx="48" cy="36" rx="16" ry="5"/><circle class="f3 sf" cx="48" cy="30" r="7"/>'},

{id:"mustard",cat:"condiments",name:{en:"Mustard",fr:"Moutarde"},latin:"Brassica juncea / Sinapis alba",
origin:{en:"Mediterranean & Asia; Dijon, France",fr:"Méditerranée & Asie ; Dijon, France"},season:[],
flavor:["hot","pungent","tangy"],
story:{en:"Romans ground the seeds into grape must — mustum ardens, “burning must”, gave mustard its name. The popes at Avignon kept an official Grand Moutardier du Pape, and Dijon built a gastronomic empire on the little seed’s fire.",
fr:"Les Romains broyaient les graines dans du moût de raisin — mustum ardens, « moût brûlant », donna son nom à la moutarde. Les papes d’Avignon entretenaient un Grand Moutardier du Pape, et Dijon bâtit un empire gastronomique sur le feu de la petite graine."},
tip:{en:"Heat kills its bite: whisk it in off the flame to finish a sauce. It is also nature’s emulsifier — the secret spine of every vinaigrette.",
fr:"La chaleur tue son mordant : incorporez-la hors du feu pour finir une sauce. C’est aussi l’émulsifiant de la nature — la colonne vertébrale secrète de toute vinaigrette."},
pairs:["pork","chicken","tarragon","honey","egg","beef","dill"],
svg:'<path class="f1 sf" d="M38 40h20v26q0 8-10 8t-10-8z"/><path class="f2 sf" d="M36 34h24v6H36z"/><path class="dot" d="M44 52a1.6 1.6 0 103.2 0 1.6 1.6 0 10-3.2 0M50 58a1.6 1.6 0 103.2 0 1.6 1.6 0 10-3.2 0M44 62a1.6 1.6 0 103.2 0 1.6 1.6 0 10-3.2 0"/>'},

{id:"niboshi",cat:"condiments",name:{en:"Niboshi",fr:"Niboshi (sardines séchées)"},latin:"Engraulis japonicus (dried)",
origin:{en:"Seto Inland Sea",fr:"Mer intérieure de Seto"},season:[],
flavor:["umami","briny","bitter","marine"],
story:{en:"Niboshi are boiled and sun-dried within a single day, and west of Osaka the same fish is called iriko instead — one product, two names, split along an old dialect line. Their oils oxidise quickly, so unlike katsuobushi they are kept cold and thrown out at the end of a season rather than aged.",
fr:"Les niboshi sont bouillis puis séchés au soleil dans la même journée, et à l'ouest d'Osaka le même poisson s'appelle iriko : un seul produit, deux noms, séparés par une vieille frontière dialectale. Leurs huiles s'oxydent vite ; contrairement au katsuobushi, on les garde au froid et on les jette en fin de saison au lieu de les affiner."},
tip:{en:"Pinch off the head and pull out the black gut before brewing, then steep them cold overnight instead of boiling. Anything above a simmer draws out exactly the bitterness the gutting was meant to prevent.",
fr:"Ôtez la tête et retirez l'intestin noir avant l'infusion, puis laissez-les macérer une nuit à froid plutôt que de les faire bouillir. Au-delà du frémissement, on extrait précisément l'amertume que l'éviscération devait éviter."},
pairs:["kombu","soy-sauce","miso","daikon","soba-noodles","hon-mirin"],
svg:'<path class="f2 sf" d="M18 40q16-10 32 0l10-6v12l-10-6q-16 10-32 0z"/><path class="f1 sf" d="M26 56q16-10 32 0l10-6v12l-10-6q-16 10-32 0z"/><path class="f2 sf" d="M24 70q14-8 28 0l8-5v10l-8-5q-14 8-28 0z"/><circle class="dot" cx="24" cy="39" r="1.6"/><circle class="dot" cx="32" cy="55" r="1.6"/>'},

{id:"nutritional-yeast",cat:"condiments",name:{en:"Nutritional yeast",fr:"Levure maltée"},latin:"Saccharomyces cerevisiae",
origin:{en:"North America & Europe",fr:"Amérique du Nord & Europe"},season:[],
flavor:["umami","nutty","toasty"],
story:{en:"It is grown on purpose on molasses, then killed with heat and dried — unlike brewer's yeast, which is what is left over after beer. The B12 on the label is always added: yeasts cannot make that vitamin, and unfortified flakes contain none.",
fr:"On la cultive exprès sur de la mélasse, puis on la tue à la chaleur et on la sèche — contrairement à la levure de bière, qui est ce qui reste après le brassage. La B12 affichée est toujours ajoutée : les levures ne savent pas fabriquer cette vitamine, et des flocons non enrichis n’en contiennent aucune."},
tip:{en:"Toast the flakes dry in a pan for a minute before using them and the nutty note doubles. A tablespoon whisked into a béchamel off the heat gives a cheese-sauce backbone without cheese.",
fr:"Torréfiez les flocons à sec une minute avant usage, la note de noisette double. Une cuillère à soupe fouettée dans une béchamel hors du feu donne un fond de sauce au fromage sans fromage."},
pairs:["cashew","garlic","kale","corn","potato","mustard","black-pepper","tomato"],
svg:'<path class="f1 sf" d="M28 54q0-12 14-12t14 12-14 12-14-12z"/><path class="f2 sf" d="M32 46q10-10 20 0z"/><path class="s" d="M56 48l14-12"/><circle class="dot" cx="64" cy="58" r="2"/><circle class="dot" cx="70" cy="64" r="2"/>'},

{id:"olive",cat:"condiments",name:{en:"Olive",fr:"Olive"},latin:"Olea europaea",
origin:{en:"Mediterranean basin",fr:"Bassin méditerranéen"},season:[9,10,11],
flavor:["briny","bitter","fruity","rich"],
story:{en:"Straight from the tree an olive is inedibly bitter — someone, thousands of years ago, had the patience to discover that brine and time perform a miracle. Green and black are the same fruit, picked young or ripe; the dove brought Noah an olive branch, and it has meant peace ever since.",
fr:"Cueillie sur l’arbre, l’olive est d’une amertume immangeable — quelqu’un, il y a des millénaires, eut la patience de découvrir que la saumure et le temps font un miracle. Verte ou noire, c’est le même fruit, cueilli jeune ou mûr ; la colombe rapporta à Noé un rameau d’olivier, symbole de paix depuis."},
tip:{en:"Buy them with their stones — pitted olives trade flavour for convenience. Warmed briefly with citrus zest and herbs, they become another ingredient entirely.",
fr:"Achetez-les avec leur noyau — dénoyautées, elles troquent le goût contre la commodité. Tiédies avec un zeste d’agrume et des herbes, elles deviennent un tout autre ingrédient."},
pairs:["lemon","anchovy","tomato","fennel","capers","oregano"],
svg:'<ellipse class="f3 sf" cx="42" cy="56" rx="9" ry="11"/><ellipse class="f1 sf" cx="58" cy="52" rx="8" ry="10"/><path class="s" d="M50 40q0-10 8-14"/><path class="f2 sf" d="M56 28q6-6 12-4-3 8-12 6z"/>'},

{id:"oyster-sauce",cat:"condiments",name:{en:"Oyster sauce",fr:"Sauce d’huître"},latin:"Crassostrea spp. (reduction)",
origin:{en:"Guangdong, China",fr:"Guangdong, Chine"},season:[],
flavor:["umami","salty","sweet","rich"],
story:{en:"The sauce exists because a Guangdong cook left a pot of oyster soup on the fire too long in 1888 and came back to a dark reduction; Lee Kum Sheung sold it, and the house he founded is still the biggest name on the shelf. Worth remembering when reading a label: many bottles now list water, sugar and starch ahead of any oyster.",
fr:"La sauce existe parce qu’un cuisinier du Guangdong a laissé en 1888 une marmite de soupe d’huîtres trop longtemps sur le feu et y a retrouvé une réduction brune ; Lee Kum Sheung l’a vendue, et la maison qu’il a fondée reste la plus connue du rayon. Ce qui vaut d’être rappelé à la lecture des étiquettes : beaucoup de bouteilles annoncent aujourd’hui l’eau, le sucre et l’amidon avant la moindre huître."},
tip:{en:"Add it at the end, off a hard flame — its sugars scorch and turn bitter in a wok. A teaspoon per portion, and cut the soy sauce back, since it already brings salt, sugar and thickener.",
fr:"Ajoutez-la en fin de cuisson, hors de la grande flamme : ses sucres brûlent et tournent à l’amer dans un wok. Une cuillerée à café par personne, et réduisez la sauce soja, car elle apporte déjà sel, sucre et liant."},
pairs:["chinese-broccoli","garlic","shaoxing-wine","ginger","sesame-oil","beef","choy-sum"],
svg:'<path class="f2 sf" d="M42 20h12v10l8 12v34a4 4 0 0 1-4 4H38a4 4 0 0 1-4-4V42l8-12z"/><rect class="f1 sf" x="37" y="50" width="22" height="18" rx="1"/><path class="s" d="M42 60q6-7 12 0"/><path class="s" d="M42 24h12"/>'},

{id:"perry-vinegar",cat:"condiments",name:{en:"Perry vinegar",fr:"Vinaigre de poiré"},latin:"Pyrus communis",
origin:{en:"Domfront, Normandy",fr:"Domfront, Normandie"},season:[],
flavor:["sour","fruity","floral"],
story:{en:"A perry pear takes fifteen years or more to come into fruit, which is where the English advice about planting pears for your heirs comes from; the Domfront orchards still hold trees two centuries old. Vinegar from their cider is softer than an apple's, because pears leave behind sorbitol the yeasts cannot ferment.",
fr:"Un poirier à poiré met quinze ans ou plus à entrer en production — d’où le conseil anglais de planter des poires pour ses héritiers ; les vergers de Domfront gardent des arbres bicentenaires. Le vinaigre tiré de leur cidre est plus doux que celui de pomme : la poire laisse du sorbitol que les levures ne fermentent pas."},
tip:{en:"Deglaze pork or andouille with it and add no sugar — it carries some already. One spoonful into the pan juices off the heat is the whole seasoning.",
fr:"Déglacez un porc ou une andouille avec, et n’ajoutez pas de sucre, il en porte déjà. Une cuillère dans le jus, hors du feu, fait tout l’assaisonnement."},
pairs:["pork","andouille","pear","camembert","shallot","walnut","celeriac","duck"],
svg:'<path class="f2 sf" d="M48 34q10 0 14 10t0 20-14 8-14-8 0-20 14-10z"/><path class="f2 sf" d="M45 20h6v16h-6z"/><path class="f3 sf" d="M44 14h8v6h-8z"/><path class="s" d="M36 60q12 6 24 0"/>'},

{id:"ponzu",cat:"condiments",name:{en:"Ponzu",fr:"Ponzu"},latin:"Citrus junos",
origin:{en:"Japan",fr:"Japon"},season:[],
flavor:["citrus","salty","umami","tangy"],
story:{en:"The name is half Dutch: pons, the Nagasaki traders' word for punch, joined to su, vinegar. Strictly, ponzu is only the citrus juice — what is sold in bottles is ponzu shoyu, that juice let down with soy, mirin, kombu and katsuobushi and rested for weeks.",
fr:"Le nom est à moitié néerlandais : pons, le mot des marchands de Nagasaki pour le punch, soudé à su, vinaigre. À la lettre, le ponzu n’est que le jus d’agrume ; ce qu’on vend en bouteille est du ponzu shoyu, ce jus allongé de sauce soja, de mirin, de kombu et de katsuobushi, puis reposé des semaines."},
tip:{en:"Add it at the table, never in the pan — the citrus aromatics are gone within a minute of heat. Cut it half and half with dashi for a dressing that will not overwhelm raw fish.",
fr:"Ajoutez-le à table, jamais dans la poêle : les arômes d’agrume partent en une minute de chaleur. Coupez-le moitié-moitié de dashi pour une sauce qui n’écrase pas un poisson cru."},
pairs:["yuzu","katsuobushi","kombu","daikon","tuna","scallop","hon-mirin","napa-cabbage"],
svg:'<path class="f1 sf" d="M28 44h20v22q0 6-6 6H34q-6 0-6-6z"/><path class="f3 sf" d="M32 36h12v8H32z"/><path class="s" d="M48 50l8-4"/><path class="f2 sf" d="M76 66a12 12 0 00-24 0z"/><path class="s" d="M64 66V54M58 66l4-10M70 66l-4-10"/>'},

{id:"preserved-lemon",cat:"condiments",name:{en:"Preserved lemon",fr:"Citron confit"},latin:"Limon salsus",
origin:{en:"Morocco",fr:"Maroc"},season:[],
flavor:["salty","sour","citrus","floral"],
story:{en:"Salt draws the water out and the bitterness with it, and after a month the peel is soft, translucent and tastes of something the fresh fruit never did. Moroccan kitchens keep a jar going permanently, topping it up rather than emptying it.",
fr:"Le sel tire l’eau et l’amertume avec elle, et après un mois l’écorce est molle, translucide et a un goût que le fruit frais n’a jamais eu. Les cuisines marocaines entretiennent un bocal en permanence, le complétant plutôt que le vidant."},
tip:{en:"The peel is the ingredient, not the pulp — scrape the flesh out and discard it. And rinse the rind unless the dish wants salt.",
fr:"C’est l’écorce l’ingrédient, non la pulpe — raclez la chair et jetez-la. Et rincez le zeste si le plat n’appelle pas de sel."},
pairs:["olive","chicken","cumin","cilantro","olive-oil","garlic","saffron","harissa"],
svg:'<path class="f2 sf" d="M40 74V38h16v36z"/><path class="s" d="M40 46h16"/><circle class="f2 sf" cx="44" cy="58" r="5"/><circle class="f2 sf" cx="53" cy="66" r="5"/>'},

{id:"red-wine-vinegar",cat:"condiments",name:{en:"Red wine vinegar",fr:"Vinaigre de vin rouge"},latin:"Acetum vini rubri",
origin:{en:"France & Italy",fr:"France & Italie"},season:[],
flavor:["sour","tangy","fruity","earthy"],
story:{en:"The word is a plain description — vin aigre, sour wine — and for most of history it was an accident rather than a product. Roman soldiers drank it diluted as posca, which is what was offered to Christ on the cross.",
fr:"Le mot est une description sans détour — vin aigre — et pendant presque toute l’histoire ce fut un accident plutôt qu’un produit. Les soldats romains le buvaient allongé d’eau sous le nom de posca, et c’est ce qui fut offert au Christ en croix."},
tip:{en:"Deglaze a pan with it rather than wine when you want the acidity to survive reduction. Wine loses its edge, vinegar keeps it.",
fr:"Déglacez à sa place plutôt qu’au vin quand vous voulez que l’acidité survive à la réduction. Le vin s’émousse, le vinaigre tient."},
pairs:["shallot","olive-oil","oyster","black-pepper","mustard","garlic","thyme","onion"],
svg:'<path class="f1 sf" d="M40 76V40h16v36z"/><path class="s" d="M40 48h16"/><path class="f1 sf" d="M44 36V26h8v10z"/>'},

{id:"kome-koji",cat:"condiments",name:{en:"Rice koji",fr:"Koji de riz"},latin:"Aspergillus oryzae",
origin:{en:"Japan",fr:"Japon"},season:[],
flavor:["sweet","toasty","mild","earthy"],
story:{en:"Aspergillus oryzae was named Japan's national fungus in 2006: sake, miso, shoyu, mirin and amazake all begin with rice it has grown through. The spores are not made by the brewers but bought from a handful of seed-mould houses, some of them centuries old, which supply the whole country.",
fr:"Aspergillus oryzae a été proclamé champignon national du Japon en 2006 : saké, miso, shoyu, mirin et amazake commencent tous par du riz qu’il a traversé. Les spores ne sont pas produites par les brasseurs mais achetées à une poignée de maisons semencières, certaines vieilles de plusieurs siècles, qui fournissent tout le pays."},
tip:{en:"Its amylase dies above roughly 60°C, so amazake is held at 55–60 for six to eight hours and never simmered. Fresh koji keeps a week chilled and freezes well; dried wants an hour's soak before it does anything at all.",
fr:"Son amylase meurt au-delà d’environ 60 °C : l’amazake se tient donc à 55-60 °C pendant six à huit heures et ne mijote jamais. Le koji frais se garde une semaine au froid et se congèle bien ; le séché demande une heure de réhydratation avant d’agir."},
pairs:["rice","soy-bean","salt","shio-koji","hon-mirin","sake-kasu"],
svg:'<path class="f2 sf" d="M22 54h52l-6 20H28z"/><path class="f1 sf" d="M28 54q8-14 20-14t20 14z"/><circle class="dot" cx="42" cy="48" r="1.5"/><circle class="dot" cx="52" cy="46" r="1.5"/><path class="s" d="M28 62h40"/>'},

{id:"rice-vinegar",cat:"condiments",name:{en:"Rice vinegar",fr:"Vinaigre de riz"},latin:"Acetum oryzae",
origin:{en:"China & Japan",fr:"Chine & Japon"},season:[],
flavor:["sour","sweet","mild","delicate"],
story:{en:"Far gentler than any European vinegar — around half the acidity — which is why sushi rice can be seasoned with it heavily without becoming sharp. Japan has made it since rice wine has existed, which is a very long time.",
fr:"Bien plus doux que tout vinaigre européen — environ moitié moins acide — d’où la possibilité d’en assaisonner généreusement le riz à sushi sans le rendre mordant. Le Japon en fait depuis que le saké existe, c’est-à-dire depuis très longtemps."},
tip:{en:"Check whether it is seasoned. Sushi vinegar already contains sugar and salt, and using it as plain vinegar wrecks a dressing.",
fr:"Vérifiez s’il est assaisonné. Le vinaigre à sushi contient déjà sucre et sel, et l’employer comme vinaigre nature détruit une vinaigrette."},
pairs:["soy-sauce","ginger","sesame-oil","rice","cucumber","spring-onion","chili","sesame"],
svg:'<path class="f3 sf" d="M40 76V40h16v36z"/><path class="s" d="M40 48h16"/><ellipse class="f3 sf" cx="48" cy="30" rx="7" ry="5"/>'},

{id:"sababushi",cat:"condiments",name:{en:"Sababushi",fr:"Sababushi (maquereau séché)"},latin:"Scomber japonicus (dried, smoked)",
origin:{en:"Japan",fr:"Japon"},season:[],
flavor:["umami","smoky","rich","meaty"],
story:{en:"Made exactly like katsuobushi — simmered, boned, smoked over weeks — but from mackerel, which carries far more fat than skipjack and leaves a darker, sweeter broth. Soba houses keep it for precisely that: a dashi with enough body to stand up to the black soy of a tsuyu.",
fr:"Fabriqué exactement comme le katsuobushi — mijoté, désarêté, fumé pendant des semaines — mais à partir du maquereau, bien plus gras que la bonite, qui laisse un bouillon plus sombre et plus doux. Les maisons de soba le gardent précisément pour cela : un dashi assez charpenté pour tenir tête au soja noir d’un tsuyu."},
tip:{en:"Its fat turns bitter if boiled: steep the shavings at about 80 °C for two minutes, then strain — never squeeze the flakes.",
fr:"Sa graisse tourne à l’amer si on la fait bouillir : infusez les copeaux à 80 °C environ pendant deux minutes, puis filtrez — sans jamais presser les flocons."},
pairs:["kombu","soy-sauce","hon-mirin","soba-noodles","shiitake","negi","katsuobushi"],
svg:'<path class="f3 sf" d="M26 54q6-18 22-22 16-4 22 8 2 10-10 18-16 10-28 6-8-2-6-10z"/><path class="s" d="M34 50q10-8 22-8M32 58q12-6 26-6"/><path class="f1 sf" d="M22 68q10-6 18-2-6 6-14 6-5 0-4-4z"/>'},

{id:"saikyo-miso",cat:"condiments",name:{en:"Saikyo miso",fr:"Saikyo miso (miso blanc de Kyoto)"},latin:"Glycine max (fermented)",
origin:{en:"Kyoto",fr:"Kyoto"},season:[],
flavor:["sweet","umami","mild","creamy"],
story:{en:"Kyoto's white miso ferments for weeks rather than years, with roughly twice as much rice koji as soybean and around five percent salt against twelve in a red one. Saikyo is properly a Kyoto maker's name rather than a category: what it sells is shiro miso, sweet enough to finish a dessert cream.",
fr:"Le miso blanc de Kyoto fermente des semaines et non des années, avec environ deux fois plus de koji de riz que de soja et quelque cinq pour cent de sel, contre douze pour un miso rouge. Saikyo est proprement le nom d’une maison de Kyoto plutôt qu’une catégorie : ce qu’elle vend est un shiro miso, assez doux pour finir une crème de dessert."},
tip:{en:"For saikyo-yaki, thin it with sake and mirin, bed the fish in it for one to three days, then wipe it off completely before grilling — left on, its sugars go from pale to black in seconds under a flame.",
fr:"Pour un saikyo-yaki, détendez-le au saké et au mirin, couchez-y le poisson un à trois jours, puis essuyez-le entièrement avant de griller : laissé en place, ses sucres passent du blond au noir en quelques secondes."},
pairs:["sea-bass","scallop","hon-mirin","junmai-sake","turnip","mitsuba"],
svg:'<path class="f2 sf" d="M28 54q0-11 13-11t13 11q0 9-13 9t-13-9z"/><path class="f1 sf" d="M54 50l20-7v7l-20 6z"/><path class="f1 sf" d="M31 50q7-13 21-3z"/><path class="s" d="M37 48q6-4 10 0"/>'},

{id:"saishikomi-shoyu",cat:"condiments",name:{en:"Saishikomi shoyu",fr:"Sauce soja saishikomi (double brassage)"},latin:"Glycine max (double-brewed)",
origin:{en:"Yanai, Yamaguchi",fr:"Yanai, Yamaguchi"},season:[],
flavor:["umami","rich","salty","toasty"],
story:{en:"Instead of brine, the second brew is mashed with finished soy sauce: twice the raw material, twice the time, and a liquid dark and thick enough to look like molasses. Yanai in Yamaguchi has made it for generations under the name kanro shoyu, sweet dew.",
fr:"À la place de la saumure, la seconde fermentation se fait sur de la sauce soja finie : deux fois la matière première, deux fois le temps, et un liquide assez sombre et épais pour évoquer la mélasse. Yanai, dans la préfecture de Yamaguchi, la produit depuis des générations sous le nom de kanro shoyu, « rosée douce »."},
tip:{en:"Keep it for the table and for finishing; heat drives off exactly the aroma that justifies the price. It is no saltier than an ordinary shoyu but far more concentrated, so pour half what you otherwise would, and refrigerate the bottle once opened.",
fr:"Gardez-la pour la table et les finitions : la chaleur emporte précisément l’arôme qui la justifie. Elle n’est pas plus salée qu’une shoyu ordinaire mais bien plus concentrée — versez-en moitié moins, et réfrigérez la bouteille une fois ouverte."},
pairs:["tuna","sea-bream","rice","wasabi","scallop","egg","silken-tofu"],
svg:'<path class="f1 sf" d="M30 44h34l-4 22q-1 8-13 8t-13-8z"/><path class="f1 sf" d="M60 44l12-5-2 9-10 2z"/><path class="f3 sf" d="M33 56h28l-2 10q-1 6-12 6t-12-6z"/><circle class="dot" cx="73" cy="56" r="2.5"/>'},

{id:"sake-kasu",cat:"condiments",name:{en:"Sake kasu",fr:"Lie de saké (sake kasu)"},latin:"Oryza sativa (lees)",
origin:{en:"Sake breweries, Japan",fr:"Brasseries de saké, Japon"},season:[1,2,3,4],
flavor:["rich","sweet","warm","creamy"],
story:{en:"What comes off the press at the end of a sake brew is a pale cake still holding around eight percent alcohol and the enzymes that made the sake. Breweries sold it cheap to their neighbours through the cold months, which is how kasujiru soup and narazuke pickles came to exist at all.",
fr:"Ce qui sort du pressoir à la fin d’un brassage de saké est un gâteau pâle qui contient encore environ huit pour cent d’alcool et les enzymes qui ont fait le saké. Les brasseries le vendaient pour trois fois rien à leurs voisins pendant les mois froids : c’est de là que viennent la soupe kasujiru et les pickles narazuke."},
tip:{en:"Loosen it in warm water or sake before it goes near a pan; dropped in as a lump it stays a lump. For fish, salt the fillet, pat it dry, bury it in thinned lees for a day or two, and cook it knowing the alcohol has not entirely gone.",
fr:"Détendez-le à l’eau chaude ou au saké avant qu’il n’approche une casserole : jeté en bloc, il reste en blocs. Pour un poisson, salez le filet, épongez-le, enfouissez-le un à deux jours dans la lie détendue, et cuisez en sachant que l’alcool n’est pas entièrement parti."},
pairs:["cod","salmon","daikon","carrot","negi","kome-koji","butter"],
svg:'<path class="f1 sf" d="M26 36h44l-4 30-16 6-24-4z"/><path class="s" d="M34 44q10 4 22 0M32 56q12 4 26-2"/><path class="f2 sf" d="M50 72l16-6-2 9z"/><circle class="dot" cx="30" cy="74" r="2"/>'},

{id:"salt",cat:"condiments",name:{en:"Salt",fr:"Sel"},latin:"Natrii chloridum",
origin:{en:"Sea and rock, everywhere",fr:"Mer et roche, partout"},season:[],
flavor:["salty","mild","briny","fresh"],
story:{en:"The only rock we eat, and the only seasoning with no substitute. Roman soldiers were paid partly in it — salarium, the root of salary — and the gabelle, France's salt tax, was hated enough to be listed among the grievances of 1789.",
fr:"La seule roche que nous mangeons, et le seul assaisonnement sans substitut. Les soldats romains étaient payés en partie avec — salarium, la racine de salaire — et la gabelle, l’impôt français sur le sel, fut assez détestée pour figurer parmi les doléances de 1789."},
tip:{en:"Salt early for anything you want seasoned through, late for anything you want to stay crisp. It draws water either way.",
fr:"Salez tôt ce que vous voulez assaisonner à cœur, tard ce que vous voulez garder croquant. Il tire l’eau dans les deux cas."},
pairs:["black-pepper","butter","olive-oil","lemon","tomato","radish","beurre-demi-sel","maple-syrup"],
svg:'<path class="f3 sf" d="M38 74V44h20v30z"/><path class="s" d="M38 52h20"/><circle class="dot" cx="44" cy="62" r="1.6"/><circle class="dot" cx="52" cy="60" r="1.6"/><circle class="dot" cx="48" cy="68" r="1.6"/>'},

{id:"sakura-leaf",cat:"condiments",name:{en:"Salted cherry leaf",fr:"Feuille de cerisier saumurée (sakura)"},latin:"Prunus serrulata",
origin:{en:"Izu peninsula, Japan",fr:"Péninsule d'Izu, Japon"},season:[],
flavor:["salty","floral","herbal"],
story:{en:"A fresh cherry leaf smells of almost nothing; the almond-and-hay perfume is coumarin, and it appears only after weeks in salt, once the glycoside holding it has broken down. Most of the supply is Oshima cherry, grown on the Izu peninsula for its large soft leaves rather than for fruit or blossom.",
fr:"Une feuille de cerisier fraîche ne sent presque rien : le parfum d'amande et de foin est la coumarine, et il n'apparaît qu'après des semaines de salaison, une fois rompu le glycoside qui la retenait. L'essentiel provient du cerisier oshima, cultivé dans la péninsule d'Izu pour ses grandes feuilles souples, non pour son fruit ni pour sa fleur."},
tip:{en:"Rinse the leaf and soak it ten minutes in fresh water before wrapping, then taste it — still fiercely salty means five minutes more. It is eaten with the mochi, not peeled off and left on the plate.",
fr:"Rincez la feuille et faites-la dessaler dix minutes à l'eau claire avant d'enrouler, puis goûtez-la : franchement salée encore, comptez cinq minutes de plus. Elle se mange avec le mochi, on ne la retire pas pour la laisser sur l'assiette."},
pairs:["glutinous-rice","adzuki","matcha","sugar","cream","junmai-sake","white-chocolate"],
svg:'<circle class="f1 sf" cx="48" cy="48" r="18"/><path class="f3 sf" d="M26 44q10 26 34 26 8-16-6-26-14-8-28 0z"/><path class="s" d="M28 46q16 18 30 22"/><path class="dot" d="M36 60a1.5 1.5 0 0 1 3 0a1.5 1.5 0 0 1-3 0M46 68a1.5 1.5 0 0 1 3 0a1.5 1.5 0 0 1-3 0M56 62a1.5 1.5 0 0 1 3 0a1.5 1.5 0 0 1-3 0"/>'},

{id:"sambal-oelek",cat:"condiments",name:{en:"Sambal oelek",fr:"Sambal oelek"},latin:"Capsicum annuum",
origin:{en:"Java, Indonesia",fr:"Java, Indonésie"},season:[],
flavor:["hot","fresh","salty","tangy"],
story:{en:"The name is the tool: ulek is the grinding stroke made in a flat stone mortar, and the Dutch spelling oelek came through the colony intact. Indonesia counts hundreds of named sambals, and this is the one defined by what it leaves out - no garlic, no sugar, no fermentation, no cooking.",
fr:"Le nom, c’est l’outil : ulek désigne le geste d’écrasement dans un mortier de pierre plat, et l’orthographe néerlandaise oelek a traversé la colonie intacte. L’Indonésie compte des centaines de sambals nommés ; celui-ci se définit par ce qu’il n’a pas — ni ail, ni sucre, ni fermentation, ni cuisson."},
tip:{en:"A teaspoon stands in for a fresh chilli anywhere, and unlike sriracha it brings no sugar you then have to correct. Stir it in off the heat: fried, it loses the raw brightness that is the whole reason to keep a jar.",
fr:"Une cuillerée à café remplace un piment frais partout, et contrairement à la sriracha elle n’apporte aucun sucre à rattraper. Incorporez-le hors du feu : frit, il perd le mordant cru qui justifie sa présence."},
pairs:["garlic","shallot","lime","fish-sauce","palm-sugar","shrimp-paste","peanut","egg"],
svg:'<path class="f2 sf" d="M22 50h52q-4 20-14 24H36q-10-4-14-24z"/><path class="s" d="M22 50h52"/><path class="f3 sf" d="M58 18q5 0 5 5l-4 26h-6l-3-26q0-5 5-5z" transform="rotate(18 58 36)"/><path class="s" d="M30 44q6-10 16-8"/>'},

{id:"sauerkraut",cat:"condiments",name:{en:"Sauerkraut",fr:"Choucroute"},latin:"Brassica oleracea fermentata",
origin:{en:"China, then Central Europe",fr:"Chine, puis Europe centrale"},season:[],
flavor:["sour","salty","fresh","earthy"],
story:{en:"Labourers on the Great Wall were fed fermented cabbage two thousand years ago, and the technique reached Europe later by way of the steppe. Captain Cook carried barrels of it and lost not a single man to scurvy on a three-year voyage.",
fr:"Les ouvriers de la Grande Muraille étaient nourris de chou fermenté il y a deux mille ans, et la technique gagna l’Europe plus tard par la steppe. Le capitaine Cook en emporta des barriques et ne perdit pas un homme au scorbut en trois ans de voyage."},
tip:{en:"Rinse it if it is aggressively sour, but keep some of the brine for the pot. Long slow cooking with fat is what mellows it.",
fr:"Rincez-la si elle est trop acide, mais gardez un peu de saumure pour la casserole. C’est la cuisson longue et grasse qui l’adoucit."},
pairs:["pork","juniper","lard","potato","caraway","onion","black-pepper","bay-leaf"],
svg:'<path class="f3 sf" d="M32 70V50h32v20z"/><path class="s" d="M34 56q6 4 12 0t12 0M34 63q6 4 12 0t12 0"/>'},

{id:"sencha",cat:"condiments",name:{en:"Sencha",fr:"Sencha"},latin:"Camellia sinensis var. sinensis",
origin:{en:"Ujitawara, Kyoto prefecture",fr:"Ujitawara, préfecture de Kyoto"},season:[4,5],
flavor:["grassy","bitter","fresh"],
story:{en:"Nagatani Soen presented the method in 1738 after fifteen years of trials: steam the picked leaf, then roll and dry it by hand — the step that keeps Japanese green tea green where pan-fired Chinese leaf goes yellow. Nothing shades these bushes, so the catechins that shade would have suppressed are all still there, and the astringency is the subject rather than the fault.",
fr:"Nagatani Sōen présente sa méthode en 1738, après quinze ans d’essais : étuver la feuille cueillie, puis la rouler et la sécher à la main — le geste qui garde vert le thé japonais quand la feuille chinoise, chauffée à la poêle, jaunit. Rien n’ombre ces théiers : les catéchines que l’ombre aurait bridées sont toutes là, et l’astringence est le sujet, non le défaut."},
tip:{en:"70–80 °C, sixty seconds, and empty the pot to the last drop — the tail of the infusion is where the bitterness collects. The second steep wants hotter water and half the time.",
fr:"70–80 °C, soixante secondes, et videz la théière jusqu’à la dernière goutte : c’est la fin de l’infusion qui rassemble l’amertume. La deuxième infusion demande une eau plus chaude et deux fois moins de temps."},
pairs:["rice","salmon","cucumber","sesame","ginger","umeboshi"],
svg:'<path class="f2 sf" d="M34 26c5 8 6 30 0 44-6-14-5-36 0-44z"/><path class="f2 sf" d="M48 20c6 10 7 36 0 52-7-16-6-42 0-52z"/><path class="f2 sf" d="M62 26c5 8 6 30 0 44-6-14-5-36 0-44z"/><path class="s" d="M34 32v32M48 28v38M62 32v32"/>'},

{id:"shaoxing-wine",cat:"condiments",name:{en:"Shaoxing wine",fr:"Vin de Shaoxing"},latin:"Oryza sativa var. glutinosa (brewed)",
origin:{en:"Shaoxing, Zhejiang",fr:"Shaoxing, Zhejiang"},season:[],
flavor:["warm","rich","umami","fruity"],
story:{en:"Shaoxing has brewed rice wine in clay jars sealed with lotus leaf and mud for centuries, and the custom of nü'er hong is still told there — a jar buried when a daughter is born, opened at her wedding. What matters in a kitchen is the ageing: oxidised and amber, the aroma sits closer to a dry sherry than to sake.",
fr:"Shaoxing brasse depuis des siècles son vin de riz dans des jarres de terre scellées à la feuille de lotus et à l’argile, et l’on y raconte encore le nü’er hong : une jarre enterrée à la naissance d’une fille, ouverte à son mariage. Ce qui compte en cuisine, c’est le vieillissement — oxydé, ambré, l’arôme est plus proche d’un xérès sec que d’un saké."},
tip:{en:"Buy the drinkable bottle, not the one labelled cooking wine — that one is salted so it can be sold as a foodstuff, and it takes the seasoning of the dish out of your hands. Splash it down the side of a hot wok so it flashes off.",
fr:"Achetez la bouteille que l’on boit, pas celle étiquetée vin de cuisine : cette dernière est salée pour être vendue comme denrée, et vous retire la main sur l’assaisonnement. Versez-la le long du wok brûlant pour qu’elle s’évapore d’un coup."},
pairs:["ginger","spring-onion","soy-sauce","pork-belly","chicken","star-anise","crab"],
svg:'<path class="f2 sf" d="M36 36q-11 10-11 22t11 16q12 4 24 0t11-16-11-22z"/><path class="f2 sf" d="M42 26h12v10H42z"/><path class="f1 sf" d="M37 27q11-9 22 0-11 5-22 0z"/><path class="s" d="M42 31h12"/>'},

{id:"sherry-vinegar",cat:"condiments",name:{en:"Sherry vinegar",fr:"Vinaigre de Xérès"},latin:"Vinagre de Jerez DOP",
origin:{en:"Jerez, Andalusia",fr:"Jerez, Andalousie"},season:[],
flavor:["sour","nutty","rich","woody"],
story:{en:"Aged in the solera system, the same cascade of stacked barrels used for the wine: each cask is partly drawn off and topped up from the one above, so a bottle contains a blend of many years and no single vintage exists.",
fr:"Vieilli en solera, la même cascade de fûts empilés que pour le vin : chaque tonneau est partiellement soutiré et complété par celui du dessus, si bien qu’une bouteille contient un assemblage de nombreuses années et qu’aucun millésime n’existe."},
tip:{en:"It is strong enough to use by the teaspoon. A few drops finish a lentil soup or a gazpacho better than a whole lemon.",
fr:"Il est assez puissant pour s’employer à la cuillère à café. Quelques gouttes finissent une soupe de lentilles ou un gaspacho mieux qu’un citron entier."},
pairs:["olive-oil","almond","iberico-ham","lentils","garlic","tomato","chickpeas","paprika"],
svg:'<path class="f1 sf" d="M40 76V40h16v36z"/><path class="s" d="M40 48h16M44 60h8"/><path class="f2 sf" d="M44 36V26h8v10z"/>'},

{id:"shio-koji",cat:"condiments",name:{en:"Shio-koji",fr:"Shio-koji"},latin:"Aspergillus oryzae (salted)",
origin:{en:"Northern Japan",fr:"Nord du Japon"},season:[],
flavor:["salty","umami","sweet","mild"],
story:{en:"Rice koji, salt and water blended and left a week at room temperature make a slurry whose enzymes work both ends of the problem: protease cuts protein into free amino acids, amylase turns starch into sugar. An old northern preserving trick, it became a national habit in Japan around 2011.",
fr:"Du koji de riz, du sel et de l’eau mixés et laissés une semaine à température ambiante donnent une bouillie dont les enzymes travaillent des deux côtés : la protéase coupe les protéines en acides aminés libres, l’amylase transforme l’amidon en sucre. Vieille ruse de conservation du nord du Japon, elle est devenue une habitude nationale autour de 2011."},
tip:{en:"Ten percent of the weight of whatever you are curing: thirty minutes for a fish fillet, four to twenty-four hours for chicken. Scrape it off before it meets heat or the sugars burn, and never leave fish overnight — the protease keeps working and the flesh goes soft.",
fr:"Dix pour cent du poids de ce que vous marinez : trente minutes pour un filet de poisson, quatre à vingt-quatre heures pour une volaille. Raclez-le avant toute cuisson, sinon les sucres brûlent, et ne laissez pas un poisson toute la nuit : la protéase continue et la chair devient molle."},
pairs:["chicken","cod","cucumber","turnip","pork","salmon","egg"],
svg:'<path class="f1 sf" d="M30 42h36v26a8 8 0 0 1-8 8H38a8 8 0 0 1-8-8z"/><path class="f2 sf" d="M31 54h34v14a8 8 0 0 1-8 8H39a8 8 0 0 1-8-8z"/><path class="f3 sf" d="M56 46l14-17 4 3-15 17z"/><circle class="dot" cx="42" cy="64" r="1.6"/><circle class="dot" cx="53" cy="69" r="1.6"/>'},

{id:"shiokara",cat:"condiments",name:{en:"Shiokara",fr:"Shiokara"},latin:"Todarodes pacificus (fermented)",
origin:{en:"Japan",fr:"Japon"},season:[],
flavor:["umami","salty","pungent","briny"],
story:{en:"Squid cut into strips and left to break down in its own salted liver — the traditional cure runs near twelve per cent salt at room temperature, the supermarket version five per cent and refrigerated. The three styles are named by colour: red with the liver, white without it, black with the ink stirred through.",
fr:"Du calmar taillé en lanières que l’on laisse se défaire dans son propre foie salé — la salaison traditionnelle tourne autour de douze pour cent de sel à température ambiante, la version de supermarché à cinq pour cent et au froid. Les trois styles portent le nom d’une couleur : rouge avec le foie, blanc sans lui, noir avec l’encre."},
tip:{en:"Treat it as a seasoning, not a dish: a teaspoon through hot rice, into butter for grilled squid, or into a cream sauce does the work of a whole tube of anchovy paste. Rinse the spoonful in sake if the liver note is too loud.",
fr:"Traitez-le en assaisonnement, pas en plat : une cuillère à café dans du riz chaud, dans un beurre pour du calmar grillé ou dans une sauce crémée fait le travail d’un tube entier de pâte d’anchois. Rincez la cuillerée au saké si la note de foie parle trop fort."},
pairs:["rice","cucumber","junmai-sake","negi","butter","yuzu","daikon"],
svg:'<path class="f1 sf" d="M28 46h40l-4 26q-1 6-16 6t-16-6z"/><path class="s" d="M24 46h48"/><path class="f3 sf" d="M34 46q4-8 14-8t14 8z"/><path class="s" d="M40 58q8 4 16 0"/>'},

{id:"shiro-shoyu",cat:"condiments",name:{en:"Shiro shoyu",fr:"Sauce soja blanche (shiro)"},latin:"Triticum aestivum (fermented)",
origin:{en:"Hekinan, Aichi",fr:"Hekinan, Aichi"},season:[],
flavor:["salty","umami","sweet","mild"],
story:{en:"Shiro shoyu inverts the recipe — roughly nine parts wheat to one of soybean — and brews for months rather than years, around Hekinan in Aichi. It comes out the colour of straw, which is the entire point: it seasons a clear broth or a chawanmushi without tinting it.",
fr:"Le shiro shoyu inverse la recette — environ neuf parts de blé pour une de soja — et fermente des mois plutôt que des années, autour de Hekinan, dans l’Aichi. Il en sort couleur paille, et c’est tout l’intérêt : il assaisonne un bouillon clair ou un chawanmushi sans le teinter."},
tip:{en:"It is as salty as any shoyu, so dose it like one. What it cannot do is last: add it at the end of cooking, keep the bottle cold and finish it within two months, because it browns and goes flat quickly once opened.",
fr:"Il est aussi salé que n’importe quelle shoyu : dosez-le comme telle. Ce qu’il ne sait pas faire, c’est durer — ajoutez-le en fin de cuisson, gardez la bouteille au froid et finissez-la en deux mois, car il brunit et s’éteint vite une fois ouverte."},
pairs:["egg","scallop","hamo","kombu","hon-mirin","silken-tofu","ginkgo-nut"],
svg:'<path class="f1 sf" d="M43 22h8v8l6 12v32a4 4 0 0 1-4 4H41a4 4 0 0 1-4-4V42l6-12z"/><rect class="f3 sf" x="42" y="17" width="10" height="6" rx="1"/><path class="s" d="M37 52h20"/><path class="f2 sf" d="M67 44q6 1 6 5t-6 5q-6-1-6-5t6-5zM67 56q6 1 6 5t-6 5q-6-1-6-5t6-5z"/><path class="s" d="M67 76V42"/>'},

{id:"smoked-salt",cat:"condiments",name:{en:"Smoked sea salt",fr:"Sel fumé"},latin:"Sodium chloride (cold-smoked)",
origin:{en:"Northern Europe",fr:"Europe du Nord"},season:[],
flavor:["smoky","salty","woody"],
story:{en:"It is cold-smoked, never heated: the crystals sit over smouldering wood for a day or more at a temperature that will neither melt nor dry them, taking the smoke on as an aroma rather than a coating. Colour tells you the wood - alder gives a pale gold, oak and beech a deeper brown.",
fr:"Il est fumé à froid, jamais chauffé : les cristaux passent une journée ou plus au-dessus d’un bois qui couve, à une température qui ne les fait ni fondre ni sécher, et prennent la fumée comme un arôme et non comme un enrobage. La couleur trahit le bois — l’aulne donne un or pâle, le chêne et le hêtre un brun plus profond."},
tip:{en:"The aroma is volatile, so it goes on at the table or off the heat; cooked into a braise it disappears and you have paid for plain salt. A pinch on eggs, butter or a boiled potato is where it reads loudest.",
fr:"Son arôme est volatil : il se met à table ou hors du feu ; fondu dans un braisé, il disparaît et vous avez payé du sel ordinaire. Une pincée sur des œufs, du beurre ou une pomme de terre à l’eau est là où il parle le plus fort."},
pairs:["egg","butter","potato","scallop","pork","dark-chocolate","tomato","cream"],
svg:'<path class="f1 sf" d="M28 60h40q-4 14-20 14t-20-14z"/><path class="s" d="M28 60h40"/><path class="dot" d="M40 54a2 2 0 104 0 2 2 0 10-4 0M50 50a2 2 0 104 0 2 2 0 10-4 0M58 56a2 2 0 104 0 2 2 0 10-4 0"/><path class="s" d="M42 44q6-6 0-12t6-12M58 42q6-6 0-12"/>'},

{id:"soy-sauce",cat:"condiments",name:{en:"Soy sauce",fr:"Sauce soja"},latin:"Glycine max (fermented)",
origin:{en:"China",fr:"Chine"},season:[],
flavor:["salty","umami","rich","toasty"],
story:{en:"Born in China over two thousand years ago as a way to stretch precious salt, brewed from soybeans, wheat and patient moulds. Some Japanese breweries have kept their mash tubs alive for centuries — the microbes are the family heirloom.",
fr:"Née en Chine il y a plus de deux mille ans pour économiser le sel précieux, brassée à partir de soja, de blé et de moisissures patientes. Certaines brasseries japonaises font vivre leurs cuves depuis des siècles — les microbes sont l’héritage de famille."},
tip:{en:"Think of it as liquid seasoning, not just an Asian marker: a teaspoon deepens a beef stew, a vinaigrette or even a caramel.",
fr:"Pensez-la comme un assaisonnement liquide, pas seulement un marqueur asiatique : une cuillerée approfondit un bœuf mijoté, une vinaigrette, voire un caramel."},
pairs:["ginger","rice","sesame","shiitake","salmon","beef","tuna"],
svg:'<path class="f3 sf" d="M42 34h12l4 10v24q0 8-10 8t-10-8V44z"/><path class="f1 sf" d="M44 26h8l2 8H42z"/><path class="s" d="M48 20v6"/>'},

{id:"squid-ink",cat:"condiments",rare:true,name:{en:"Squid ink",fr:"Encre de seiche"},latin:"Sepia officinalis (ink)",
origin:{en:"Mediterranean coasts",fr:"Côtes méditerranéennes"},season:[],
flavor:["marine","briny","umami","rich"],
story:{en:"The cephalopod’s smoke bomb, turned into the kitchen’s most dramatic pigment. Venice stirs it into risotto nero, Catalonia into arròs negre — dishes that arrive black as a new moon and taste, against all appearance, of gentle sea and sweet rice.",
fr:"L’écran de fumée du céphalopode, devenu le pigment le plus théâtral de la cuisine. Venise le glisse dans le risotto nero, la Catalogne dans l’arròs negre — des plats qui arrivent noirs comme une nuit sans lune et qui ont, contre toute apparence, un goût de mer douce et de riz sucré."},
tip:{en:"A teaspoon suffices for a whole pan of rice; add it with the stock, not at the end, so the brininess cooks in and mellows.",
fr:"Une cuillerée suffit pour toute une poêlée de riz ; ajoutez-la avec le bouillon, pas à la fin, pour que le salin cuise et s’assagisse."},
pairs:["rice","garlic","shrimp","olive-oil"],
svg:'<path class="f3 sf" d="M40 32h16l-3 10q8 4 8 14 0 12-13 12t-13-12q0-10 8-14z"/><path class="f3" d="M60 62q6 4 10 2M36 62q-6 4-10 2" fill="none"/><path class="s" d="M60 62q6 4 10 2M36 62q-6 4-10 2" stroke-width="1.8"/>'},

{id:"sriracha",cat:"condiments",name:{en:"Sriracha",fr:"Sriracha"},latin:"ศรีราชา",
origin:{en:"Si Racha, Thailand",fr:"Si Racha, Thaïlande"},season:[],
flavor:["hot","sweet","tangy","pungent"],
story:{en:"Named for a seaside town in Thailand, though the version most of the world knows was made in California by a Vietnamese refugee, David Tran, who named his company after the freighter that carried him out. The rooster on the bottle is his zodiac sign.",
fr:"Nommée d’après une ville balnéaire thaïlandaise, bien que la version connue du monde entier ait été créée en Californie par un réfugié vietnamien, David Tran, qui baptisa son entreprise du nom du cargo qui l’avait emmené. Le coq de la bouteille est son signe zodiacal."},
tip:{en:"It is as much vinegar and sugar as chilli, so it works as a glaze. Brush it on in the last minutes of roasting.",
fr:"Elle est autant vinaigre et sucre que piment, ce qui en fait un bon laquage. Badigeonnez-en dans les dernières minutes de cuisson."},
pairs:["garlic","lime","fish-sauce","honey","soy-sauce","egg","spring-onion","sesame"],
svg:'<path class="f1 sf" d="M40 76V38h16v38z"/><path class="s" d="M40 46h16"/><path class="f3 sf" d="M44 34V26h8v8z"/>'},

{id:"tahini",cat:"condiments",name:{en:"Tahini",fr:"Tahini"},latin:"طحينة",
origin:{en:"Levant",fr:"Levant"},season:[],
flavor:["nutty","bitter","rich","toasty"],
story:{en:"Ground sesame and nothing else, and it does something counterintuitive: stir water into it and it seizes and thickens before suddenly loosening into a pale, smooth cream. Cooks who do not expect that throw away the first batch.",
fr:"Du sésame broyé et rien d’autre, avec un comportement contre-intuitif : ajoutez-y de l’eau et elle se fige et s’épaissit avant de se détendre brusquement en une crème pâle et lisse. Ceux qui ne s’y attendent pas jettent la première tentative."},
tip:{en:"Keep adding the water through the seizing stage. It always comes back, and it takes far more water than seems possible.",
fr:"Continuez d’ajouter l’eau pendant la phase de figeage. Elle revient toujours, et il en faut bien plus qu’on ne l’imagine."},
pairs:["lemon","garlic","chickpeas","cumin","olive-oil","date","honey","parsley"],
svg:'<path class="f3 sf" d="M36 70V48q12-4 24 0v22z"/><path class="s" d="M36 48q12 4 24 0"/><ellipse class="dot" cx="44" cy="60" rx="2" ry="1.4"/><ellipse class="dot" cx="53" cy="63" rx="2" ry="1.4"/>'},

{id:"takuan",cat:"condiments",name:{en:"Takuan",fr:"Takuan (daïkon mariné)"},latin:"沢庵漬け",
origin:{en:"Japan",fr:"Japon"},season:[],
flavor:["sweet","tangy","pungent","umami"],
story:{en:"Whole daikon are hung in the wind for weeks until they can be bent into a hoop without breaking, and only then are they buried in rice bran and salt for several months. The name belongs to Takuan Soho, a seventeenth-century Zen abbot; the story goes that he served the pickle to a shogun who declared it should carry his name.",
fr:"Les daïkons entiers sèchent au vent pendant des semaines, jusqu’à pouvoir être pliés en cerceau sans casser ; ce n’est qu’ensuite qu’on les enfouit plusieurs mois dans le son de riz et le sel. Le nom est celui de Takuan Sōhō, abbé zen du XVIIe siècle : on raconte qu’il servit ce condiment à un shogun qui décréta qu’il porterait son nom."},
tip:{en:"Rinse the bran off and cut it 2-3 mm across the round - the noise it makes is half the point, and thin shavings lose it. It belongs cold at the end of a rice meal; laid on anything hot it slackens within a minute.",
fr:"Rincez le son et taillez-le en rondelles de 2 à 3 mm : le bruit qu’il fait compte pour moitié, et les copeaux fins le perdent. Il se sert froid, en fin de repas de riz ; posé sur un plat chaud, il s’avachit en une minute."},
pairs:["rice","miso","cucumber","sesame","soy-sauce","nori","sencha"],
svg:'<path class="f2 sf" d="M28 42h30v26H28z"/><ellipse class="f2 sf" cx="58" cy="55" rx="6" ry="13"/><ellipse class="f1 sf" cx="28" cy="55" rx="6" ry="13"/><ellipse class="f1 sf" cx="72" cy="62" rx="5" ry="11"/>'},

{id:"tamari",cat:"condiments",name:{en:"Tamari",fr:"Tamari"},latin:"たまり",
origin:{en:"Chūbu region, Japan",fr:"Région du Chūbu, Japon"},season:[],
flavor:["umami","salty","rich","earthy"],
story:{en:"Originally the liquid that pooled on top of fermenting miso — tamari means that which accumulates. It is made with little or no wheat, which is why it is darker, rounder and less sharp than ordinary soy sauce.",
fr:"À l’origine le liquide qui s’accumulait sur le miso en fermentation — tamari signifie ce qui s’amasse. Il se fait avec peu ou pas de blé, d’où sa couleur plus sombre, sa rondeur et sa moindre vivacité que la sauce soja ordinaire."},
tip:{en:"Use it where soy sauce would dominate — as a dipping sauce, or brushed on grilled fish. It seasons without shouting.",
fr:"Employez-le là où la sauce soja domineriez — en sauce à tremper, ou au pinceau sur un poisson grillé. Il assaisonne sans crier."},
pairs:["ginger","sesame-oil","rice","tuna","spring-onion","wasabi","shiitake","sesame"],
svg:'<path class="f1 sf" d="M40 76V40h16v36z"/><path class="s" d="M40 48h16"/><path class="f1 sf" d="M44 36V26h8v10z"/><circle class="dot" cx="48" cy="60" r="3"/>'},

{id:"tamarind-paste",cat:"condiments",name:{en:"Tamarind paste",fr:"Pâte de tamarin"},latin:"Tamarindus indica",
origin:{en:"East Africa & India",fr:"Afrique de l’Est & Inde"},season:[],
flavor:["sour","fruity","sweet","earthy"],
story:{en:"The name comes from the Arabic tamr hindi, date of India, although the tree is African - medieval traders carried it east and the misnomer travelled with it. Its sourness is mostly tartaric acid, the acid of grapes rather than of lemons, which is why it reads round and deep where citrus reads sharp.",
fr:"Le nom vient de l’arabe tamr hindi, « datte de l’Inde », alors que l’arbre est africain : les marchands médiévaux l’ont porté vers l’est et le contresens a voyagé avec lui. Son acidité est surtout tartrique — l’acide du raisin, non celui du citron — d’où cette rondeur profonde là où les agrumes tranchent."},
tip:{en:"Block tamarind is soaked twenty minutes in hot water and pushed through a sieve; the jarred concentrate is two to three times stronger and much darker, so start at a third of the quantity and taste. It thickens as it reduces - add it early in a curry for body, late in a dressing for edge.",
fr:"Le bloc de tamarin se trempe vingt minutes à l’eau chaude puis se passe au tamis ; le concentré en pot est deux à trois fois plus fort et bien plus sombre : partez d’un tiers de la quantité et goûtez. Il épaissit en réduisant — mettez-le tôt dans un curry pour le corps, tard dans une sauce pour le tranchant."},
pairs:["palm-sugar","fish-sauce","chili","garlic","ginger","coconut-milk","peanut","shallot"],
svg:'<path class="f2 sf" d="M30 28q-4 26 18 40 8 5 12-1t-6-9Q38 46 40 28q1-7-5-7t-5 7z"/><path class="s" d="M36 44q6 4 12 6M44 52q5 3 10 4"/><path class="f3 sf" d="M56 66q8-4 12 2t-6 8-8-4z"/>'},

{id:"umeboshi",cat:"condiments",rare:true,name:{en:"Umeboshi",fr:"Umeboshi"},latin:"Prunus mume (salted)",
origin:{en:"Japan",fr:"Japon"},season:[],
flavor:["sour","salty","fruity","pungent"],
story:{en:"Ume — an apricot cousin, not a plum — salted for months and blushed crimson with red shiso. Samurai carried them as field rations against fatigue, and a single one centred on white rice makes the hinomaru bentō: lunch as the Japanese flag.",
fr:"L’ume — cousin de l’abricot, non de la prune — salé des mois durant et rougi au shiso pourpre. Les samouraïs l’emportaient en ration de campagne contre la fatigue, et un seul, posé au centre d’un riz blanc, fait le hinomaru bentō : le déjeuner en drapeau japonais."},
tip:{en:"Use the flesh as a paste: a fingertip’s worth wakes a rice bowl, a dressing or steamed greens with salt and lightning at once.",
fr:"Utilisez la chair comme une pâte : l’équivalent d’un bout de doigt réveille un bol de riz, une sauce ou des légumes vapeur — sel et éclair à la fois."},
pairs:["rice","shiso","sesame","honey"],
svg:'<circle class="f3 sf" cx="48" cy="54" r="15"/><path class="s" d="M42 48q-2 6 1 11M48 39v-6" stroke-width="1.6"/><path class="f2 sf" d="M48 33q6-5 11-3-2 6-9 6z"/>'},

{id:"umezu",cat:"condiments",name:{en:"Umezu",fr:"Vinaigre d’umeboshi (umezu)"},latin:"Prunus mume",
origin:{en:"Japan, the umeboshi barrels",fr:"Japon, les barriques d’umeboshi"},season:[],
flavor:["salty","sour","fresh","herbal"],
story:{en:"Despite the name, umezu is not a vinegar: it is the brine the ume plums give up under salt, drawn off before the fruit goes out to dry in the July sun. The pink arrives only afterwards, when red shiso leaves are packed in and their pigment turns scarlet against the acid.",
fr:"Malgré son nom, l’umezu n’est pas un vinaigre : c’est la saumure que les prunes ume rendent sous le sel, soutirée avant que les fruits ne partent sécher au soleil de juillet. Le rose ne vient qu’ensuite, lorsqu’on tasse les feuilles de shiso rouge dont le pigment vire à l’écarlate au contact de l’acide."},
tip:{en:"Count it as salt and acid at once — a teaspoon replaces both the vinegar and the salt in a vinaigrette, so season only after tasting. Never reduce it: heat carries off the shiso perfume and leaves flat brine behind.",
fr:"Comptez-le comme sel et acide à la fois : une cuillère à café remplace le vinaigre et le sel d’une vinaigrette, ne salez donc qu’après avoir goûté. Ne le faites jamais réduire, la chaleur emporte le parfum de shiso et ne laisse qu’une saumure plate."},
pairs:["cucumber","daikon","shiso","rice","avocado","ginger"],
svg:'<path class="f2 sf" d="M34 34h28v28q0 8-8 8H42q-8 0-8-8z"/><path class="s" d="M32 28h32v6H32z"/><circle class="f3 dot" cx="44" cy="52" r="6"/><circle class="f1 sf" cx="56" cy="58" r="5"/><path class="s" d="M48 22q10-6 14 2-8 5-14-2z"/>'},

{id:"usukuchi-soy-sauce",cat:"condiments",name:{en:"Usukuchi (light soy sauce)",fr:"Sauce soja claire (usukuchi)"},latin:"薄口醤油",
origin:{en:"Tatsuno, Hyogo",fr:"Tatsuno, Hyōgo"},season:[],
flavor:["salty","umami","delicate","mild"],
story:{en:"Brewed at Tatsuno in Hyogo from the seventeenth century for the clear dashi cooking of the Kansai, it ferments for less time, at a higher salt content, with a little amazake added - all of which hold the colour back. It is roughly two percentage points saltier than dark shoyu, so the pale bottle is the strong one.",
fr:"Brassée à Tatsuno, dans le Hyōgo, depuis le XVIIe siècle pour la cuisine claire au dashi du Kansai, elle fermente moins longtemps, à teneur en sel plus élevée, avec un peu d’amazaké — autant de freins à la coloration. Elle est environ deux points plus salée que la sauce soja foncée : la bouteille pâle est la plus forte."},
tip:{en:"Swapping it for dark shoyu, use about a fifth less and correct at the end. Keep it for dishes where the colour of the broth is the dish - a clear suimono, simmered white turnip, chawanmushi.",
fr:"Pour remplacer la sauce soja foncée, comptez un cinquième de moins et rectifiez en fin de cuisson. Réservez-la aux plats où la couleur du bouillon fait le plat : un suimono clair, un navet mijoté, un chawanmushi."},
pairs:["kombu","katsuobushi","hon-mirin","daikon","junmai-sake","rice","scallop","hakurei-turnip"],
svg:'<path class="f1 sf" d="M36 44q0-8 6-10h12q6 2 6 10v26q0 6-6 6H42q-6 0-6-6z"/><path class="f2 sf" d="M54 34l14-10 3 4-14 10z"/><path class="s" d="M36 60h24"/><path class="f2 sf" d="M42 28h12v6H42z"/>'},

{id:"usukuchi-shoyu",cat:"condiments",name:{en:"Usukuchi shoyu",fr:"Sauce soja claire (usukuchi)"},latin:"Glycine max",
origin:{en:"Tatsuno, Harima, Japan",fr:"Tatsuno, Harima, Japon"},season:[],
flavor:["salty","umami","mild","delicate"],
story:{en:"Brewed at Tatsuno in the 1660s so that the clear broths of Kansai would stay clear, usukuchi is paler than ordinary shoyu and yet saltier: the brine is stronger and the mash pressed younger, so it never darkens. Amazake, a sweet rice mash, goes in at the end of brewing, which is why so pale a sauce tastes so round.",
fr:"Brassée à Tatsuno dans les années 1660 pour que les bouillons clairs du Kansai le restent, l’usukuchi est plus pâle que la sauce courante et pourtant plus salée : la saumure est plus forte et le moût pressé plus jeune, si bien qu’elle ne fonce jamais. On y ajoute en fin de brassage de l’amazake, une bouillie de riz sucrée, ce qui explique qu’une sauce si claire ait autant de rondeur."},
tip:{en:"Use about three quarters of what a recipe asks in ordinary shoyu and taste before adding more: usukuchi carries a couple of points more salt. In a dashi for chawanmushi or udon it seasons without browning the egg or the broth.",
fr:"Comptez les trois quarts de la dose prévue en sauce courante et goûtez avant d’en remettre : l’usukuchi porte deux points de sel de plus. Dans un dashi de chawanmushi ou d’udon, elle assaisonne sans brunir ni l’œuf ni le bouillon."},
pairs:["kombu","katsuobushi","hon-mirin","daikon","egg","mitsuba"],
svg:'<path class="f2 sf" d="M44 24h8v10l10 12v22q0 4-4 4H38q-4 0-4-4V46l10-12z"/><path class="s" d="M42 24h12"/><path class="f1" d="M36 56h24v14q0 2-2 2H38q-2 0-2-2z"/><path class="s" d="M40 62h16"/>'},

{id:"verjus",cat:"condiments",rare:true,name:{en:"Verjuice",fr:"Verjus"},latin:"Vitis vinifera (green juice)",
origin:{en:"Medieval Europe & Persia",fr:"Europe médiévale & Perse"},season:[],
flavor:["sour","fruity","fresh","tangy"],
story:{en:"The pressed juice of unripe grapes — medieval Europe’s everyday acid before lemons were affordable, and the original soul of Dijon mustard. Sommeliers revived it for a precise reason: unlike vinegar, its gentle acidity doesn’t wage war on the wine in your glass.",
fr:"Le jus pressé de raisins verts — l’acide quotidien de l’Europe médiévale avant que le citron ne soit abordable, et l’âme originelle de la moutarde de Dijon. Les sommeliers l’ont ressuscité pour une raison précise : contrairement au vinaigre, son acidité douce ne fait pas la guerre au vin dans votre verre."},
tip:{en:"Deglaze a chicken pan with it, or dress a salad destined to meet a good bottle. It sharpens without stinging.",
fr:"Déglacez-en une poêle de poulet, ou assaisonnez une salade destinée à croiser une bonne bouteille. Il aiguise sans piquer."},
pairs:["chicken","mustard","tarragon","scallop","grape"],
svg:'<path class="f1 sf" d="M44 24h8v12q6 4 6 12v22q0 8-10 8t-10-8V48q0-8 6-12z"/><path class="f2" d="M40 54a4.5 4.5 0 109 0 4.5 4.5 0 10-9 0M47 62a4 4 0 108 0 4 4 0 10-8 0"/>'},

{id:"vin-de-paille",cat:"condiments",name:{en:"Vin de paille",fr:"Vin de paille"},latin:"Vitis vinifera",
origin:{en:"Jura, dried in unheated lofts",fr:"Jura, séché en greniers non chauffés"},season:[],
flavor:["sweet","honeyed","fruity"],
story:{en:"The bunches are laid on straw or hung in an unheated loft for at least six weeks and pressed between Christmas and late February; a hundred kilos of shrivelled grapes yield fifteen to eighteen litres of must. Nothing is added at any point — the sweetness is only the water that left.",
fr:"Les grappes reposent sur un lit de paille ou pendent au grenier non chauffé six semaines au minimum, puis passent au pressoir entre Noël et la fin février : cent kilos de raisins passerillés rendent quinze à dix-huit litres de moût. On n’ajoute rien à aucun moment — la douceur n’est que l’eau partie."},
tip:{en:"Deglaze with it off the heat and reduce by half at most; boiled hard it caramelises and turns bitter. A tablespoon swirled into the fat left after searing foie gras is the entire sauce.",
fr:"Déglacez hors du feu et ne réduisez pas de plus de moitié : à gros bouillons, il caramélise et amerise. Une cuillerée liée à la graisse restée dans la poêle après avoir saisi le foie gras suffit à faire toute la sauce."},
pairs:["foie-gras","apricot","pear","walnut","blue-cheese","fig"],
svg:'<path class="f2 sf" d="M48 24c6 0 10 4 10 9 5 2 7 8 4 12 2 6-2 12-6 14-2 6-6 9-8 9s-6-3-8-9c-4-2-8-8-6-14-3-4-1-10 4-12 0-5 4-9 10-9z"/><path class="s" d="M39 34q9 4 18 0M37 46q11 5 22 0M42 58q6 3 12 0"/><path class="s" d="M28 74h40M24 80h48"/><path class="s" d="M48 24V13"/>'},

{id:"vin-jaune",cat:"condiments",name:{en:"Vin jaune",fr:"Vin jaune"},latin:"Vitis vinifera (Savagnin)",
origin:{en:"Château-Chalon and Arbois, Jura",fr:"Château-Chalon et Arbois, Jura"},season:[],
flavor:["nutty","warm","umami"],
story:{en:"The barrel is filled once and never topped up again for six years and three months; a film of yeast grows across the surface and shields the wine while about a third of it evaporates. That loss is why the bottle holds 62 cl — what is left of a litre after the cellar has taken its share.",
fr:"On remplit le fût une fois, puis on ne l’ouille plus pendant six ans et trois mois : un voile de levures se forme en surface et protège le vin tandis qu’un bon tiers s’évapore. Cette perte explique le clavelin de 62 cl — ce qui reste d’un litre quand la cave a pris sa part."},
tip:{en:"Reduce it far less than you would a dry white: the sotolon that gives the curry note concentrates fast and turns acrid. Stir it into a cream sauce at the end, off the heat, and open the bottle a day ahead.",
fr:"Réduisez-le beaucoup moins qu’un blanc sec : le sotolon, qui porte la note de curry, se concentre vite et devient âcre. Incorporez-le en fin de sauce crémée, hors du feu, et ouvrez la bouteille la veille."},
pairs:["morel","cream","bresse-chicken","comte","walnut","butter"],
svg:'<path class="f2 sf" d="M43 19h10v9c0 6 9 8 9 18v28a4 4 0 0 1-4 4H38a4 4 0 0 1-4-4V46c0-10 9-12 9-18z"/><path class="s" d="M34 56h28M34 68h28"/><path class="f3 sf" d="M42 14h12v6H42z"/>'},

{id:"vin-santo",cat:"condiments",name:{en:"Vin Santo",fr:"Vin santo"},latin:"Vitis vinifera (Trebbiano)",
origin:{en:"Tuscany",fr:"Toscane"},season:[],
flavor:["nutty","sweet","woody"],
story:{en:"The dried must goes into caratelli — fifty-litre casks that are sealed shut and never topped up — each carrying a madre, a sludge of yeast and lees held back from the previous batch to start the next. Years of that, under a roof that freezes in winter and bakes in summer, is what turns it oxidative where a straw wine stays fruity.",
fr:"Le moût passerillé entre en caratelli — des fûts de cinquante litres scellés et jamais ouillés — chacun portant sa madre, un dépôt de levures et de lies gardé de la cuvée précédente pour lancer la suivante. Des années de ce régime, sous un toit qui gèle l’hiver et cuit l’été, le rendent oxydatif là où un vin de paille reste fruité."},
tip:{en:"Cook with the dry version, secco; the sweet one scorches in a hot pan. Deglaze chicken livers with two spoonfuls, let it go syrupy, then mash them for crostini.",
fr:"En cuisine, prenez le sec, le secco : le doux brûle dans une poêle chaude. Déglacez les foies de volaille de deux cuillerées, laissez sirupeux, puis écrasez pour les crostini."},
pairs:["almond","dark-chocolate","fig","hazelnut","pecorino","raisin"],
svg:'<path class="f2 sf" d="M36 28q12-4 24 0c6 12 6 28 0 40q-12 4-24 0c-6-12-6-28 0-40z"/><path class="s" d="M34 40h28M34 56h28"/><ellipse class="f3 sf" cx="48" cy="48" rx="4" ry="3"/><path class="s" d="M40 27q8-3 16 0"/>'},

{id:"moutarde-violette-brive",cat:"condiments",name:{en:"Violet mustard of Brive",fr:"Moutarde violette de Brive"},latin:"Brassica nigra & Vitis vinifera",
origin:{en:"Brive-la-Gaillarde, Correze",fr:"Brive-la-Gaillarde, Corrèze"},season:[],
flavor:["sweet","pungent","fruity","warm"],
story:{en:"The colour comes from the grapes, not the seed: the must is cooked down and the black skins dye the paste purple, with no vinegar involved at any point. Legend hands it to Pope Clement VI, a Limousin who is said to have taken his mustard-maker with him to Avignon in the fourteenth century.",
fr:"La couleur vient du raisin, non de la graine : le moût est cuit et les peaux noires teintent la pâte en violet, sans vinaigre à aucun moment. La légende l’attribue au pape Clément VI, Limousin qui aurait emmené son moutardier à Avignon au XIVe siècle."},
tip:{en:"With no vinegar it has almost no emulsifying power and will not hold a vinaigrette - use Dijon for that and keep this for the plate. Beside a duck breast, foie gras or a boudin noir it does the work of a chutney, and it dulls the moment you cook it.",
fr:"Sans vinaigre, elle n’émulsionne presque pas et ne tiendra pas une vinaigrette : gardez le dijon pour cela et celle-ci pour l’assiette. À côté d’un magret, d’un foie gras ou d’un boudin noir, elle joue le rôle d’un chutney — et elle s’éteint dès qu’on la cuit."},
pairs:["duck","foie-gras","pork","boudin-noir","comte","walnut"],
svg:'<path class="f3 sf" d="M34 46h28v26q0 6-6 6H40q-6 0-6-6z"/><path class="f2 sf" d="M30 40h36v6H30z"/><circle class="f2 sf" cx="48" cy="35" r="4"/><path class="f1 sf" d="M66 30l8 4-16 20-5-3z"/>'},

{id:"white-balsamic-condiment",cat:"condiments",name:{en:"White balsamic condiment",fr:"Condiment balsamique blanc"},latin:"Vitis vinifera (condimento bianco)",
origin:{en:"Modena & Reggio Emilia",fr:"Modène & Reggio d’Émilie"},season:[],
flavor:["sweet","tangy","fruity","mild"],
story:{en:"It is sold as a condimento and never as aceto balsamico, because the protected names require the dark cooked must. The trick is vacuum: cooking the must under reduced pressure lets it concentrate at a temperature too low to caramelise, so the sugar arrives without the colour.",
fr:"Il se vend comme condimento, jamais comme aceto balsamico : les appellations protégées exigent le moût cuit et sombre. Le procédé tient au vide — cuit sous pression réduite, le moût se concentre à une température trop basse pour caraméliser, et le sucre arrive sans la couleur."},
tip:{en:"Its acidity sits close to a wine vinegar's, so build the vinaigrette at one part to three of oil and leave out any added sugar. Reach for it wherever browning would be a fault - white fish, a pale mayonnaise, a beurre blanc, a risotto that must stay ivory.",
fr:"Son acidité avoisine celle d’un vinaigre de vin : montez la vinaigrette à un pour trois d’huile et supprimez tout sucre ajouté. Employez-le partout où le brunissement serait un défaut — poisson blanc, mayonnaise claire, beurre blanc, risotto qui doit rester ivoire."},
pairs:["asparagus","scallop","chicken","strawberry","olive-oil","shallot","white-asparagus","peach"],
svg:'<path class="f1 sf" d="M44 20h8v16l8 16v28q0 4-4 4H40q-4 0-4-4V52l8-16z"/><path class="s" d="M36 64h24"/><path class="f2 sf" d="M43 14h10v6H43z"/><path class="s" d="M64 44q6 6 6 12t-6 6-6-6 6-12z"/>'},

{id:"white-wine-vinegar",cat:"condiments",name:{en:"White wine vinegar",fr:"Vinaigre de vin blanc"},latin:"Acetum vini",
origin:{en:"Orléans, France",fr:"Orléans, France"},season:[],
flavor:["sour","tangy","fresh","fruity"],
story:{en:"Orléans became the vinegar capital of France by geography: barrels of wine came up the Loire towards Paris, and whatever soured on the journey was unloaded there. A failure of transport became a protected craft.",
fr:"Orléans devint la capitale française du vinaigre par géographie : les barriques remontaient la Loire vers Paris, et tout ce qui tournait en route y était débarqué. Un échec de transport est devenu un artisanat protégé."},
tip:{en:"The Orléans method ferments slowly in oak over weeks. Industrial vinegar is made in hours and tastes only of acid.",
fr:"La méthode orléanaise fermente lentement en chêne sur des semaines. Le vinaigre industriel se fait en heures et n’a que le goût de l’acide."},
pairs:["shallot","mustard","tarragon","olive-oil","egg","black-pepper","butter","chives"],
svg:'<path class="f3 sf" d="M40 76V40h16v36z"/><path class="s" d="M40 48h16"/><path class="f3 sf" d="M44 36V26h8v10z"/>'},

{id:"wholegrain-mustard",cat:"condiments",name:{en:"Wholegrain mustard",fr:"Moutarde à l’ancienne"},latin:"Brassica juncea",
origin:{en:"Meaux, France",fr:"Meaux, France"},season:[],
flavor:["pungent","tangy","warm","nutty"],
story:{en:"Mustard has no heat until it is broken: crushing the seed brings an enzyme to the compounds beside it, and the pungency builds in water over about ten minutes, then fades. Leaving the seed cracked rather than milled slows all of that down, which is why à l'ancienne is gentler than a Dijon made from the same batch of seed.",
fr:"La moutarde n’a aucun feu tant qu’on ne la brise pas : le broyage met une enzyme au contact des composés voisins, et le piquant se forme dans l’eau en une dizaine de minutes avant de retomber. Laisser la graine concassée plutôt que moulue ralentit tout cela, d’où une moutarde à l’ancienne plus douce qu’un dijon issu du même lot de graines."},
tip:{en:"Add it off the heat: boiling drives the pungency off within a minute and leaves a dull, faintly bitter seed. For a vinaigrette that holds, emulsify with a teaspoon of smooth Dijon and use the grain purely for texture.",
fr:"Ajoutez-la hors du feu : l’ébullition chasse le piquant en une minute et ne laisse qu’une graine terne, un peu amère. Pour une vinaigrette qui tient, émulsionnez avec une cuillerée de dijon lisse et ne mettez l’ancienne que pour la texture."},
pairs:["pork","rabbit","cream","leek","saucisse-de-morteau","honey","cider-vinegar","chicken"],
svg:'<path class="f1 sf" d="M30 46h36v26q0 6-6 6H36q-6 0-6-6z"/><path class="s" d="M26 42h44v4H26z"/><path class="dot" d="M36 54a2 2 0 104 0 2 2 0 10-4 0M46 58a2 2 0 104 0 2 2 0 10-4 0M56 54a2 2 0 104 0 2 2 0 10-4 0M42 68a2 2 0 104 0 2 2 0 10-4 0M54 66a2 2 0 104 0 2 2 0 10-4 0"/>'},

{id:"worcestershire",cat:"condiments",name:{en:"Worcestershire sauce",fr:"Sauce Worcestershire"},latin:"Garum anglicum",
origin:{en:"Worcester, England",fr:"Worcester, Angleterre"},season:[],
flavor:["umami","salty","sour","smoky"],
story:{en:"Two chemists made a batch in 1835, found it undrinkable and left the barrel in the cellar. Eighteen months later they tasted it again out of curiosity and it had fermented into something extraordinary. Anchovies are the source of the umami.",
fr:"Deux pharmaciens en firent un lot en 1835, le trouvèrent imbuvable et laissèrent le fût à la cave. Dix-huit mois plus tard ils y goûtèrent par curiosité : il avait fermenté en quelque chose d’extraordinaire. Ce sont les anchois qui apportent l’umami."},
tip:{en:"A few drops deepen anything brown — stews, gravies, a shepherd's pie. It is a seasoning, not a sauce to pour.",
fr:"Quelques gouttes approfondissent tout ce qui est brun — ragoûts, sauces, hachis. C’est un assaisonnement, non une sauce à verser."},
pairs:["beef","tomato","onion","black-pepper","garlic","butter","mustard","anchovy"],
svg:'<path class="f1 sf" d="M42 76V36h12v40z"/><path class="s" d="M42 46h12"/><path class="f3 sf" d="M44 32V24h8v8z"/>'},

{id:"gomme-xanthane",cat:"condiments",name:{en:"Xanthan gum",fr:"Gomme xanthane"},latin:"Xanthomonas campestris (exopolysaccharide)",
origin:{en:"Laboratory fermentation, Peoria, Illinois",fr:"Fermentation de laboratoire, Peoria, Illinois"},season:[],
flavor:["mild","delicate"],
story:{en:"It was found in the late 1950s at a United States Department of Agriculture laboratory in Peoria, Illinois, by a team under Allene Jeanes screening bacteria for useful polysaccharides. The producer, Xanthomonas campestris, is a plant disease that rots cabbages; the slime it secretes to glue itself to a leaf is what now holds a vinaigrette together.",
fr:"Elle a été découverte à la fin des années 1950 dans un laboratoire du ministère américain de l’Agriculture, à Peoria dans l’Illinois, par l’équipe d’Allene Jeanes qui criblait des bactéries en quête de polysaccharides utiles. La productrice, Xanthomonas campestris, est une maladie des plantes qui pourrit les choux : le mucus qu’elle sécrète pour se coller aux feuilles est ce qui tient aujourd’hui une vinaigrette."},
tip:{en:"Weigh it, never spoon it: 0.2% of the liquid's weight gives a sauce that still pours, 0.5% one that mounds, and the gap between them is a few tenths of a gram. Add it with the blender already running, or it clumps into fish eyes that never dissolve.",
fr:"Pesez-la, ne la dosez jamais à la cuillère : 0,2 % du poids du liquide donne une sauce encore coulante, 0,5 % une sauce qui tient en dôme, et l’écart se joue à quelques dixièmes de gramme. Versez-la mixeur déjà en marche, sinon elle prend en yeux de poisson qui ne se dissolvent plus."},
pairs:["olive-oil","lemon","mustard","balsamic","tomato","cream"],
svg:'<rect class="f1 sf" x="28" y="40" width="26" height="32" rx="3"/><rect class="f2 sf" x="26" y="32" width="30" height="8" rx="2"/><path class="f2 sf" d="M62 52q0-6 5-6t5 6-5 6-5-6z"/><path class="s" d="M67 58v12"/><path class="s" d="M34 52h14"/>'},

{id:"xo-sauce",cat:"condiments",name:{en:"XO sauce",fr:"Sauce XO"},latin:"—",
origin:{en:"Hong Kong",fr:"Hong Kong"},season:[],
flavor:["umami","salty","hot","rich"],
story:{en:"Hong Kong hotel kitchens built it in the 1980s and borrowed the name from XO cognac purely as a signal of expense; there is no brandy in the jar. Several restaurants claim the invention and none can prove it.",
fr:"Les cuisines des hôtels de Hong Kong l’ont mise au point dans les années 1980 et lui ont emprunté le nom du cognac XO comme simple signal de luxe : il n’y a pas une goutte d’eau-de-vie dedans. Plusieurs restaurants en revendiquent l’invention, aucun ne peut la prouver."},
tip:{en:"The flavour sits in the oil as much as in the solids, so stir the jar from the bottom and spoon up both. Add it at the end: past a minute in a hot wok the dried scallop goes bitter and the shallot turns to grit.",
fr:"Le goût est autant dans l’huile que dans les morceaux : remuez le pot depuis le fond et prélevez les deux. Ajoutez-la en fin de cuisson, au-delà d’une minute dans un wok brûlant la noix de Saint-Jacques séchée devient amère et l’échalote se réduit en gravier."},
pairs:["scallop","egg","choy-sum","rice","silken-tofu","green-bean"],
svg:'<path class="f2 sf" d="M32 38h32v26q0 6-6 6H38q-6 0-6-6z"/><path class="f3 sf" d="M30 30h36v8H30z"/><circle class="dot" cx="42" cy="50" r="3"/><circle class="dot" cx="55" cy="55" r="3"/><circle class="dot" cx="46" cy="61" r="2.5"/>'},

{id:"yeast-extract",cat:"condiments",name:{en:"Yeast extract",fr:"Extrait de levure"},latin:"Saccharomyces cerevisiae",
origin:{en:"Burton upon Trent, England",fr:"Burton upon Trent, Angleterre"},season:[],
flavor:["umami","salty","meaty","bitter"],
story:{en:"Liebig showed in the nineteenth century that yeast cells could be broken open and concentrated into something meat-like, and in 1902 a factory opened at Burton upon Trent to work through the spent yeast the town's breweries were throwing away. The savour is free glutamate released as the cell digests itself - the same molecule behind parmesan and soy sauce.",
fr:"Liebig avait montré au XIXe siècle qu’on pouvait éclater les cellules de levure et les concentrer en quelque chose de carné ; en 1902, une usine ouvrit à Burton upon Trent pour exploiter les levures usées que les brasseries de la ville jetaient. La sapidité vient du glutamate libéré quand la cellule se digère elle-même — la molécule même du parmesan et de la sauce soja."},
tip:{en:"Half a teaspoon in two litres of stock is the whole dose; beyond that it turns bitter and tastes unmistakably of itself. Dissolve it in a ladle of hot liquid first - dropped into a cold sauce it stays in lumps that never quite go.",
fr:"Une demi-cuillerée à café pour deux litres de fond suffit ; au-delà, il devient amer et se reconnaît d’emblée. Délayez-le d’abord dans une louche de liquide chaud : jeté dans une sauce froide, il forme des grumeaux qui ne partent jamais tout à fait."},
pairs:["mushroom","onion","butter","lentils","tomato","beef","carrot","soy-sauce"],
svg:'<ellipse class="f3 sf" cx="34" cy="52" rx="14" ry="8" transform="rotate(-12 34 52)"/><path class="s" d="M47 47l24-8"/><path class="f3 sf" d="M32 60q4 10 0 16t-4-16z"/><path class="dot" d="M30 82a3 3 0 106 0 3 3 0 10-6 0"/>'}
]);
